window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q09"]=window.__LIBQ["pham-nhan-tu-tien"]["q09"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q09"]["factions"]={"updatedAt":"2026-07-26","count":111,"factions":[{"id":"moc-linh-toc","name":"Mộc Linh Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Hắc Thạch Sâm Lâm","nhanVatChinh":["Ngân giai mộc linh"],"blurb":"Thế lực bị đội thám sát Nhân–Yêu lưỡng tộc theo dõi tại Hắc Thạch Sâm Lâm.","detail":"Mộc Linh Tộc bố trí Thiên Mộc Mộng La Lung Tráo tại Hắc Thạch Sâm Lâm. Nếu phát hiện đội thám sát, tộc này có thể khiến toàn đội rơi vào nguy cơ tử vong.","tranPhai":["Thiên Mộc Mộng La Lung Tráo"],"quanHe":"Là mục tiêu trinh sát của liên quân Nhân Tộc và Yêu Tộc.","tabs":{"tienTrinh":[{"chuong":"@c1354","loai":"nhắc tới","importance":"normal","giaiDoan":"Bị tiến hành thám sát","text":"Mộc Linh Tộc trở thành mục tiêu của nhiệm vụ thu thập tình báo tại Hắc Thạch Sâm Lâm.","anchor":"Thực sự nhiệm vụ lần này chỉ là thám sát động thái của Mộc Linh Tộc thôi"}]},"capNhatToi":"@c1354","nguon":["@c1354","@c1385"],"trangThai":"Đang tồn tại","thanhVien":[{"ten":"Ngân giai mộc linh","chucVu":"Cao giai mộc linh","tuChuong":"@c1385","trangThai":"Đang hoạt động"}]},{"id":"huyen-ung-toc","name":"Huyền Ưng Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Không rõ","nhanVatChinh":["Lý đạo hữu"],"blurb":"Một chủng tộc thiên cầm hiếm thấy, là xuất thân của Lý đạo hữu.","detail":"Du Hồng xác định Lý đạo hữu là người của Huyền Ưng Tộc và xem đây là một chủng tộc thiên cầm hiếm gặp.","thanhVien":[{"ten":"Lý đạo hữu","chucVu":"Tộc nhân","tuChuong":"@c1355","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1355","nguon":["@c1355"]},{"id":"moc-toc","name":"Mộc Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Phong Nguyên Đại Lục","nhanVatChinh":[],"blurb":"Một chủng tộc tại Linh giới có Đại trưởng lão đạt Đại Thừa sơ kỳ. Người của tộc đã điều tra Bảo Hoa và Tiểu Ngạc sau biến cố tại thánh địa. (+) Chủng tộc được dự đoán có thể liên quân với Ảnh Tộc để tiến đánh Nhân Tộc và Yêu Tộc. [CAN-SOAT-GOP]","detail":"Kim Việt đại sư nhận định lực lượng có khả năng tấn công Thiên Uyên Thành trước mắt là liên quân do Mộc Tộc và Ảnh Tộc hợp thành.","quanHe":"Có khả năng liên quân với Ảnh Tộc và đối đầu Nhân Tộc, Yêu Tộc.","trangThai":"Có khả năng chuẩn bị chiến tranh","tabs":{"tienTrinh":[{"chuong":"@c1356","loai":"liên minh","importance":"normal","giaiDoan":"Nguy cơ lập liên quân","text":"Mộc Tộc được nhận định có khả năng cùng Ảnh Tộc lập liên quân tấn công Nhân Tộc và Yêu Tộc.","anchor":"kẻ địch công kích chúng ta hiện nay e rằng chỉ có khả năng là liên quân Mộc Tộc và Ảnh Tộc mà thôi","trangThaiMoc":"Có khả năng liên quân với Ảnh Tộc"}]},"capNhatToi":"@c1356","nguon":["@c1356","@c1873","@c1964","@c2169"],"thanhVien":[{"ten":"Đại trưởng lão Mộc tộc","chucVu":"Đại trưởng lão","tuChuong":"@c1873","trangThai":"Đang tại vị"},{"ten":"Nữ tử Mộc tộc","chucVu":"Thành viên","tuChuong":"@c1873","trangThai":"Đang hoạt động"}]},{"id":"hac-xoa-toc","name":"Hắc Xoa Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Tây bắc Phong Nguyên Đại Lục","nhanVatChinh":[],"blurb":"Chủng tộc đang giao chiến quyết liệt với Linh Tộc tại khu vực tây bắc Phong Nguyên Đại Lục.","detail":"Hắc Xoa Tộc và Linh Tộc đang đại chiến. Kim Việt đại sư cho rằng cuộc chiến sẽ càng dữ dội nếu hai bên biết tin Huyền Thiên Trảm Linh Kiếm xuất hiện trong khu vực.","quanHe":"Đang giao chiến với Linh Tộc.","trangThai":"Đang chiến tranh","tabs":{"tienTrinh":[{"chuong":"@c1356","loai":"khai chiến","importance":"normal","giaiDoan":"Đại chiến với Linh Tộc","text":"Hắc Xoa Tộc đang giao chiến dữ dội với Linh Tộc tại tây bắc Phong Nguyên Đại Lục.","anchor":"Linh Tộc và Hắc Xoa Tộc đang đánh nhau bất kể trời đất","trangThaiMoc":"Đang giao chiến với Linh Tộc"}]},"capNhatToi":"@c1356","nguon":["@c1356"]},{"id":"thien-muc-toc-cu-nhan","name":"Thiên Mục Tộc Cự Nhân","cn":"","type":"chung-toc","typeLabel":"Chủng tộc Cự Nhân","diaBan":"Man Hoang Chi Địa","nhanVatChinh":["Thiên Mục Cự Nhân"],"blurb":"Chủng tộc Cự Nhân sống quần cư. Thành viên trưởng thành có mắt ngân bạch và cá thể xuất hiện bên Chi Long Quả mang thực lực khoảng Luyện Hư kỳ.","detail":"Tập tính sống quần cư khiến Chu Hồng nghi ngờ Thiên Mục Cự Nhân đang trì hoãn việc thu lấy Chi Long Quả để chờ đồng tộc đến viện trợ.","quyMo":"Sống quần cư","thanhVien":[{"ten":"Thiên Mục Cự Nhân","chucVu":"Thành viên trưởng thành","tuChuong":"@c1360","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1360","tabs":{"tienTrinh":[{"chuong":"@c1360","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ tập tính quần cư","text":"Tập tính sống quần cư của chủng tộc được dùng để suy đoán rằng Thiên Mục Cự Nhân đang chờ viện thủ bên Chi Long Quả.","anchor":"Cự Nhân nhất tộc đều sống quần cư, Linh Quả đã chín nhưng hắn vẫn giằng co với Thằn lằn này có thể là đang đợi viện thủ đấy","trangThaiMoc":"Được phát hiện hoạt động tại Man Hoang Chi Địa"}]},"nguon":["@c1360"]},{"id":"cac-chan-linh-the-gia","name":"Các chân linh thế gia","cn":"","type":"lien-minh-gia-toc","typeLabel":"Liên minh gia tộc huyết mạch","diaBan":"Phạm vi Nhân Tộc","nhanVatChinh":[],"blurb":"Tập hợp các gia tộc kế thừa chân linh huyết mạch và cùng duy trì giao ước bảo vệ huyết mạch.","detail":"Các chân linh thế gia nghiêm cấm thành viên tranh đoạt chân linh huyết mạch của nhau. Thế gia vi phạm giao ước có thể bị những gia tộc còn lại liên thủ tiêu diệt.","tonChi":"Ngăn cấm việc tranh đoạt chân linh huyết mạch giữa các thế gia.","quyMo":"Gồm nhiều chân linh thế gia.","quanHe":"Duy trì giao ước bảo vệ huyết mạch giữa các gia tộc.","trangThai":"đang tồn tại","capNhatToi":"@c1377","tabs":{"tienTrinh":[{"chuong":"@c1377","loai":"nhắc tới","importance":"normal","giaiDoan":"Giao ước huyết mạch","text":"Giao ước giữa các chân linh thế gia được tiết lộ, theo đó bên vi phạm lệnh cấm tranh đoạt huyết mạch sẽ bị các nhà còn lại liên thủ tiêu diệt.","anchor":"Nếu có chút vi phạm, sẽ bị tất cả thế gia liên thủ tiêu diệt","trangThaiMoc":"Giao ước đang có hiệu lực"}]},"nguon":["@c1377"]},{"id":"nhan-yeu-nhi-toc","name":"Nhân Yêu nhị tộc","cn":"","type":"chung-toc","typeLabel":"Hai tộc quần","diaBan":"","nhanVatChinh":[],"blurb":"Cách gọi chung Nhân tộc và Yêu tộc.","detail":"Một số đại tông môn và đại thần thông giả thuộc hai tộc từng thuần hóa Huyền Qua Thú để canh giữ những địa điểm quan trọng.","capNhatToi":"@c1392","nguon":["@c1392"]},{"id":"dai-quan-di-toc-mang-canh","name":"Đại quân dị tộc mang cánh","cn":"","aliases":[],"type":"quan-doi","typeLabel":"Đại quân dị tộc","diaBan":"Khu vực Man Hoang cách Thiên Uyên Thành ít nhất nửa năm lộ trình","nhanVatChinh":["Mộng Tường","Mỹ mạo nữ tử dị tộc mang cánh","Ác quỷ hai cánh","Ngân giáp dị tộc hộ vệ tổ ong","Nữ dị tộc trẻ thuộc hạ Mộng Tường","Hai dị tộc khổng lồ dưới quyền Mộng Tường"],"blurb":"Đại quân dị tộc mang cánh là một lực lượng quy mô cực lớn, gồm vô số dị tộc mang cánh, các cự vật hình tổ ong, hàng vạn cổ thú và hơn một nghìn hắc toa. Đại quân đã tiến sâu vào khu vực xa Thiên Uyên Thành, triển khai lực lượng tiên phong săn giết tu sĩ Nhân tộc và phá hủy nơi hoạt động của họ.","detail":"Đội hình đại quân liên tục xuất hiện trên bầu trời, bao gồm nhiều binh chủng và phương tiện khác nhau. Trong quá trình khai chiến, lực lượng này tiến sâu vào khu vực xa Thiên Uyên Thành; một đội ngũ tinh nhuệ do Mộng Tường chỉ huy đã lục soát cự sơn, phá hủy địa điểm hoạt động của nhóm tu sĩ Nhân tộc và bao vây những người trốn thoát. @c1394","quyMo":"Vô số chiến binh có cánh, gần trăm tổ ong khổng lồ, hàng vạn cổ thú, hơn một nghìn hắc toa và nhiều tu sĩ cấp Hóa Thần, Luyện Hư.","caoThuManhNhat":"Mộng Tường","quanHe":"Đang tiến sâu vào khu vực của Nhân tộc và săn bắt các tu sĩ hoạt động bên ngoài Thiên Uyên Thành.","trangThai":"Đang hành quân","thanhVien":[{"ten":"Mộng Tường","chucVu":"Chỉ huy lực lượng tinh nhuệ","tuChuong":"@c1394","trangThai":"Đang hoạt động"},{"ten":"Mỹ mạo nữ tử dị tộc mang cánh","chucVu":"Thành viên đội đi trước","tuChuong":"@c1394","trangThai":"Đang hoạt động"},{"ten":"Ác quỷ hai cánh","chucVu":"Thành viên đội đi trước","tuChuong":"@c1394","trangThai":"Đang hoạt động"},{"ten":"Ngân giáp dị tộc hộ vệ tổ ong","chucVu":"Hộ vệ đoàn vận chuyển","tuChuong":"@c1394","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1394","tabs":{"tienTrinh":[{"chuong":"@c1394","loai":"khai chiến","importance":"major","giaiDoan":"Tiến vào địa vực Nhân tộc","text":"Đại quân dị tộc mang cánh với nhiều binh chủng tiến sâu vào khu vực xa Thiên Uyên Thành, trong khi lực lượng tiên phong săn giết và bao vây các tu sĩ Nhân tộc.","anchor":"Những dị tộc mang cánh liên miên không dứt xuất hiện tại trên bầu trời","trangThaiMoc":"Đang hành quân và truy bắt tu sĩ Nhân tộc"}]},"nguon":["@c1394"],"uyLuc":"Quy mô mạnh nhất đã thể hiện là đội hình gồm vô số dị tộc mang cánh, hàng vạn cổ thú, các cự vật hình tổ ong và hơn một nghìn hắc toa, đủ sức tiến sâu, phá hủy cứ điểm và bao vây tu sĩ Nhân tộc.","dacDiem":"Đại quân có quy mô cực lớn, hoạt động trên bầu trời và sở hữu đội hình hỗn hợp gồm dị tộc mang cánh, cự vật hình tổ ong, cổ thú cùng hắc toa.","congNang":["Điều động nhiều binh chủng cùng các cự vật hình tổ ong, cổ thú và hắc toa tiến sâu vào khu vực xa Thiên Uyên Thành. @c1394","Triển khai lực lượng tiên phong săn giết tu sĩ Nhân tộc.","Lục soát cự sơn để truy tìm mục tiêu.","Phá hủy địa điểm hoạt động của nhóm tu sĩ Nhân tộc.","Bao vây những tu sĩ Nhân tộc thoát ra khỏi nơi bị phá hủy."]},{"id":"hao-thu-toc","name":"Hạo Thú tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Hắc Ẩn sơn và khu vực lân cận","nhanVatChinh":["Thú đầu trâu","Vị đại nhân trong sương mù đen","Ngưu giác thanh niên"],"blurb":"Chủng tộc có thần thông chuyên biệt để nhận biết và bắt sống Kim Tủy Tinh Trùng.","detail":"Thú đầu trâu và vị tiền bối nửa quỷ nửa yêu trong sương mù đen đều xuất thân từ Hạo Thú tộc. Một số tộc nhân tại Hắc Ẩn sơn đang chịu nô ngân của Thiên Bằng tộc.","dacDiem":"Có khả năng tìm Kim Tủy Tinh Trùng trong khoáng thạch và ngăn chúng hóa thành tinh thạch.","thanhVien":[{"ten":"Thú đầu trâu","chucVu":"Tộc nhân","tuChuong":"@c1404","trangThai":"đang hoạt động"},{"ten":"Vị đại nhân trong sương mù đen","chucVu":"Tiền bối","tuChuong":"@c1404","trangThai":"đang hoạt động"},{"ten":"Ngưu giác thanh niên","chucVu":"Không rõ","tuChuong":"@c1519","trangThai":"Bị nghi có liên quan"}],"tabs":{"tienTrinh":[{"chuong":"@c1404","loai":"nhắc tới","importance":"bridge","giaiDoan":"Hé lộ nguồn gốc thành viên","text":"Thú đầu trâu xác nhận vị tiền bối trong sương mù đen cũng xuất thân từ Hạo Thú tộc.","anchor":"vị tiền bối này cũng xuất thân từ Hạo Thú tộc"}]},"capNhatToi":"@c1404","nguon":["@c1404","@c1519"],"trangThai":"Không rõ"},{"id":"phi-linh-toc","name":"Phi Linh tộc","cn":"","type":"chung-toc","typeLabel":"Dị tộc có cánh","diaBan":"Khu vực đại lục và hải vực quanh Hắc Minh đảo","nhanVatChinh":["Hàn Lập","Lôi Lan","Bạch Bích","Bộ phu nhân","Diêu đạo hữu","Hung đạo hữu"],"blurb":"Phi Linh tộc là dị tộc có cánh gồm khoảng mười chi tộc, thống trị khu vực đại lục và hải vực lân cận Hắc Minh đảo. Thế lực này có hệ thống Thánh tử chịu những điều kiện hà khắc, đồng thời từng phối hợp với hai dị tộc khác để triệu hồi Huyền Thiên Trảm Linh Kiếm. (+) Quần thể các tộc đang cùng quản lý Địa Uyên. [CAN-SOAT-GOP]","detail":"Phi Linh tộc kiểm soát khu vực quanh Hắc Minh đảo, bao gồm vùng đại lục cư trú và hải vực lân cận; Hàn Lập từng phải chọn tuyến duyên hải để rời khỏi phạm vi của họ (@c1408, @c1530). Tộc gồm khoảng mười chi, trong đó Thiên Bằng tộc là một chi tương đối nhỏ. Các Thánh tử Phi Linh tộc phải tuân theo những điều kiện hà khắc; họ chỉ được tạm thời tự do hoạt động tại ba tầng trên khi không cản trở đại sự (@c1444, @c1509). Về sau, cao tầng Phi Linh tộc chấp thuận tiếp tục phối hợp với hai dị tộc nhằm triệu hồi Huyền Thiên Trảm Linh Kiếm (@c1534).","quyMo":"Khoảng mười chi tộc","quanHe":"Thiên Bằng tộc là một chi trực thuộc.","trangThai":"Đang tồn tại","tabs":{"tienTrinh":[{"chuong":"@c1408","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lộ phạm vi thống trị","text":"Ký ức của Ngư yêu mặt người cho biết khu vực quanh Hắc Minh đảo thuộc quyền thống trị của Phi Linh tộc.","anchor":"hình như là khu vực thống trị của một dị tộc có cánh gọi là Phi Linh tộc"},{"chuong":"@c1444","loai":"nhắc tới","importance":"normal","giaiDoan":"Thí luyện tại Địa Uyên","text":"Các thánh tử Phi Linh Tộc được tạm thời tự do hoạt động tại ba tầng trên nếu không cản trở đại sự hoặc xuống dưới tầng bốn.","anchor":"chỉ cần bọn họ không ảnh hưởng đến chúng ta, không tiến vào dưới tầng bốn"},{"chuong":"@c1509","loai":"nhắc tới","importance":"bridge","giaiDoan":"Nhắc tới điều kiện Thánh tử","text":"Nghiên Lệ nhắc tới những điều kiện hà khắc dành cho Thánh tử Phi Linh Tộc.","anchor":"Thánh tử Phi Linh Tộc chẳng những cần có chân linh tinh huyết mà còn nhiều những hạn chế hà khắc khác nữa"},{"chuong":"@c1530","loai":"nhắc tới","importance":"normal","giaiDoan":"Hàn Lập rời lãnh địa","text":"Hàn Lập chọn tuyến duyên hải để trực tiếp rời khỏi khu vực cư trú của Phi Linh Tộc.","anchor":"Hắn chuẩn bị men theo khu duyên hải trực tiếp bay ra khỏi khu vực cư trú của Phi Linh Tộc."},{"chuong":"@c1534","loai":"liên minh","importance":"normal","giaiDoan":"Huyết tế lần hai","text":"Các cao tầng Phi Linh Tộc chấp thuận tiếp tục phối hợp với hai dị tộc để triệu hồi Huyền Thiên Trảm Linh Kiếm.","anchor":"mấy tên phi linh tộc cấp cao khác nghe được lời ấy đều không có nửa điểm bất mãn","trangThaiMoc":"Tiếp tục hỗ trợ pháp trận"}]},"capNhatToi":"@c1408","nguon":["@c1408","@c1420","@c1444","@c1509","@c1530","@c1534","@c1593","@c1604","@c1846"],"thanhVien":[{"ten":"Hàn Lập","chucVu":"Từng mang thân phận Thánh tử","tuChuong":"@c1444","trangThai":"thân phận từng sử dụng"},{"ten":"Lôi Lan","chucVu":"Thánh tử tham gia thí luyện","tuChuong":"@c1444","trangThai":"đang hoạt động"},{"ten":"Bạch Bích","chucVu":"Thánh tử tham gia thí luyện","tuChuong":"@c1444","trangThai":"đang hoạt động"},{"ten":"Bộ phu nhân","chucVu":"Cao tầng","tuChuong":"@c1534","trangThai":"Đang tham gia huyết tế"},{"ten":"Diêu đạo hữu","chucVu":"Cao tầng","tuChuong":"@c1534","trangThai":"Đang tham gia huyết tế"},{"ten":"Hung đạo hữu","chucVu":"Người quyết định","tuChuong":"@c1534","trangThai":"Đang chỉ huy nhóm"},{"ten":"Kim Duyệt","chucVu":"Đại trưởng lão Thiên Bằng tộc","tuChuong":"@c1846","trangThai":"đang hoạt động"},{"ten":"Lôi Lan","chucVu":"Thánh chủ Thiên Bằng tộc","tuChuong":"@c1846","trangThai":"đang hoạt động"}],"uyLuc":"Phi Linh tộc có quyền thống trị toàn bộ khu vực quanh Hắc Minh đảo, bao gồm cả đại lục cư trú và hải vực lân cận.","dacDiem":"Dị tộc có cánh, gồm khoảng mười chi tộc; Thiên Bằng tộc là một chi tương đối nhỏ.","congNang":["Thống trị và kiểm soát khu vực đại lục cùng hải vực lân cận Hắc Minh đảo (@c1408, @c1530).","Tổ chức, quản thúc các Thánh tử bằng những điều kiện hà khắc, đồng thời cho phép họ tạm thời tự do hoạt động tại ba tầng trên nếu không cản trở đại sự (@c1444, @c1509).","Phối hợp với hai dị tộc khác trong kế hoạch triệu hồi Huyền Thiên Trảm Linh Kiếm (@c1534)."]},{"id":"xich-dung-toc","name":"Xích Dung tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc thuộc Phi Linh tộc","diaBan":"Xâm nhập địa bàn ven bờ của Thiên Bằng tộc","nhanVatChinh":["Thiên Minh","Chúc Âm Tử","Xích Thiên","Hồng Sa","Hán tử họ Vưu"],"blurb":"Một nhánh của Phi Linh tộc sở hữu thần thông hóa thành hỏa điểu. Đội do Thiên Minh chỉ huy xâm nhập địa bàn Thiên Bằng để cướp Hoa Mộc Linh.","detail":"Thiên Minh dẫn bảy tám đồng tộc cùng một con chim lớn hai đầu phục kích ba người Thiên Bằng, ép họ giao tài vật và quy thuận. Khi bị từ chối, đội Xích Dung triển khai Khốn Ma Võng rồi phát động vây giết.","lanhDaoHienThoi":"Thiên Minh chỉ huy đội phục kích","quanHe":"Đối địch với Thiên Bằng tộc trong cuộc tranh đoạt Hoa Mộc Linh.","trangThai":"Chia lực lượng tìm bảo vật và phục kích","thanhVien":[{"ten":"Thiên Minh","chucVu":"Chỉ huy đội phục kích","tuChuong":"@c1409","trangThai":"đang hoạt động"},{"ten":"Nhóm người Xích Dung tộc đi cùng Thiên Minh","chucVu":"Thành viên đội phục kích","tuChuong":"@c1409","trangThai":"đang hoạt động"},{"ten":"Chúc Âm Tử","chucVu":"Thánh tử, người chỉ huy","tuChuong":"@c1446","trangThai":"đang hoạt động"},{"ten":"Xích Thiên","chucVu":"Thánh tử","tuChuong":"@c1446","trangThai":"đang hoạt động"},{"ten":"Hồng Sa","chucVu":"Thánh tử","tuChuong":"@c1446","trangThai":"đang hoạt động"},{"ten":"Hán tử họ Vưu","chucVu":"Thánh tử, chỉ huy lực lượng phục kích","tuChuong":"@c1446","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1409","loai":"khai chiến","importance":"normal","giaiDoan":"Phục kích trên địa bàn đối phương","text":"Đội Xích Dung tộc do Thiên Minh chỉ huy chặn ba người Thiên Bằng, đòi Hoa Mộc Linh và ép họ quy thuận trước khi phát động vây giết.","anchor":"sau đó quy thuận Xích Dung tộc chúng ta"},{"chuong":"@c1420","loai":"liên minh","importance":"normal","giaiDoan":"Liên danh thúc đẩy thí luyện","text":"Xích Dung tộc cùng Độ Nha tộc và nhiều phân chi liên danh đề nghị tổ chức kỳ thí luyện sớm.","anchor":"Nghe nói Xích Dung tộc, Độ Nha tộc hơn mười tộc liên danh đề xuất"},{"chuong":"@c1446","loai":"khai chiến","importance":"normal","giaiDoan":"Chia quân tại cửa động","trangThaiMoc":"Đang bố trí phục kích","text":"Xích Dung Tộc chia lực lượng để vừa tìm Minh Diễm Quả vừa phục kích nhóm Thiên Bằng Tộc tại cửa xuống tầng ba.","anchor":"người của Thiên Bằng Tộc tuy nhất định phải giết, nhưng Minh Diễm Quả cũng phải có được."}]},"capNhatToi":"@c1409","nguon":["@c1409","@c1420","@c1446"]},{"id":"yeu-man-toc","name":"Yêu man tộc","cn":"","aliases":[],"type":"chủng tộc","typeLabel":"Chủng tộc","diaBan":"","nhanVatChinh":["Kim Duyệt"],"blurb":"Danh xưng được Kim Duyệt sử dụng khi mời Hàn Lập gia nhập và trở thành Thánh tử Thiên Bằng.","detail":"Quan hệ tổ chức chính xác giữa Yêu man tộc, Phi Linh tộc và Thiên Bằng tộc chưa được giải thích trong chương này.","quanHe":"Kim Duyệt tự nhận thuộc Yêu man tộc khi đưa ra lời mời với Hàn Lập.","trangThai":"Đang mời Hàn Lập gia nhập","thanhVien":[{"ten":"Kim Duyệt","chucVu":"Đại trưởng lão Thiên Bằng tộc","tuChuong":"@c1415","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1415","loai":"nhắc tới","importance":"normal","giaiDoan":"Mời Hàn Lập gia nhập","text":"Kim Duyệt dùng danh nghĩa Yêu man tộc để mời Hàn Lập gia nhập và trở thành Thánh tử của Thiên Bằng tộc.","anchor":"Hàn huynh có hứng thú gia nhập Yêu man tộc chúng ta, làm Thánh tử bổn tộc không?","trangThaiMoc":"Mời Hàn Lập gia nhập"}]},"capNhatToi":"@c1415","nguon":["@c1415"]},{"id":"van-loi-phuong","name":"Vạn Lôi Phường","cn":"","aliases":[],"type":"cua-hang","typeLabel":"Cửa hàng","diaBan":"Tầng thứ chín đại điện giao dịch","nhanVatChinh":["Nam tử khô gầy nghi là chủ tiệm","Hai người Thiên Bằng trong Vạn Lôi Phường"],"blurb":"Cửa hàng hai tầng nằm tại một góc tầng thứ chín của đại điện giao dịch. Đây là địa điểm gắn với tin rao bán Thanh La quả mà Hàn Lập tìm đến.","detail":"Cửa Vạn Lôi Phường được che bởi một quầng sáng xanh và có biển màu đỏ nhạt. Gian ngoài rộng khoảng ba bốn mươi trượng, đặt bàn gỗ đen, ghế vàng cùng các giá gỗ bày không nhiều hàng hóa.","lanhDaoHienThoi":"Nam tử khô gầy nghi là chủ tiệm","quyMo":"Cửa hàng hai tầng","thanhVien":[{"ten":"Nam tử khô gầy nghi là chủ tiệm","chucVu":"Nghi là chủ tiệm","tuChuong":"@c1417","trangThai":"Đang hiện diện"},{"ten":"Hai người Thiên Bằng trong Vạn Lôi Phường","chucVu":"Không rõ","tuChuong":"@c1417","trangThai":"Đang hiện diện"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1417","tabs":{"tienTrinh":[{"chuong":"@c1417","loai":"nhắc tới","importance":"normal","giaiDoan":"Hàn Lập tìm tới","text":"Hàn Lập lần theo tin rao bán Thanh La quả và tiến vào Vạn Lôi Phường trên tầng thứ chín.","anchor":"trên cửa lộ ra một cái biển màu đỏ nhạt, mặt trên chớp động viết “Vạn Lôi Phường”.","trangThaiMoc":"Đang hoạt động"}]},"nguon":["@c1417"]},{"id":"do-nha-toc","name":"Độ Nha tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Phân chi Phi Linh tộc","diaBan":"","nhanVatChinh":[],"blurb":"Một phân chi Phi Linh tộc tham gia thúc đẩy kỳ thí luyện diễn ra sớm.","detail":"Độ Nha tộc cùng Xích Dung tộc và hơn mười phân chi khác liên danh đề nghị tổ chức kỳ thí luyện sớm với lý do địa uyên bất ổn.","tabs":{"tienTrinh":[{"chuong":"@c1420","loai":"liên minh","importance":"normal","giaiDoan":"Liên danh thúc đẩy thí luyện","text":"Độ Nha tộc tham gia liên danh yêu cầu kỳ thí luyện được tổ chức sớm.","anchor":"Nghe nói Xích Dung tộc, Độ Nha tộc hơn mười tộc liên danh đề xuất"}]},"capNhatToi":"@c1420","nguon":["@c1420"]},{"id":"hoi-lien-tich-cac-truong-lao","name":"Hội liên tịch các trưởng lão","cn":"","aliases":["Liên tịch trưởng lão hội"],"type":"hoi-dong","typeLabel":"Cơ cấu Phi Linh tộc","diaBan":"","nhanVatChinh":[],"blurb":"Cơ cấu trưởng lão liên tịch có quyền quyết định thời điểm tổ chức kỳ thí luyện của các phân chi Phi Linh tộc.","detail":"Đa số thành viên đồng ý tổ chức kỳ thí luyện sớm, khiến Thiên Bằng tộc dù phản đối vẫn phải chấp nhận thời hạn chỉ còn hai tháng.","trangThai":"Đã thông qua việc tổ chức thí luyện sớm","tabs":{"tienTrinh":[{"chuong":"@c1420","loai":"nhắc tới","importance":"normal","giaiDoan":"Thông qua thí luyện sớm","text":"Hội liên tịch các trưởng lão thông qua đề nghị tổ chức kỳ thí luyện sớm.","anchor":"liên tịch trưởng lão và nhiều người đã đồng ý thí luyện sớm"}]},"capNhatToi":"@c1420","nguon":["@c1420"]},{"id":"ngu-quang-toc","name":"Ngũ Quang Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"","nhanVatChinh":["Thu phu nhân"],"blurb":"Chủng tộc từng luyện chế mười Tu Di Động Thiên Đồ từ linh cốt Ngũ Sắc Khổng Tước. Ba phế phẩm có tỳ vết bị giữ kín nhưng cuối cùng thất lạc ra ngoài tộc. (+) Chủng tộc có liên hệ với truyền thừa Ngũ sắc thần quang và Ngũ sắc Khổng Tước biến thân. [CAN-SOAT-GOP]","detail":"Trong mười Tu Di Động Thiên Đồ được luyện chế, bảy món hoàn chỉnh được công khai còn ba món có tỳ vết bị che giấu. Tu Di Động Thiên Đồ của điếm chủ họ Ngư là một trong những phế phẩm đã thất lạc.","nguonGoc":"Từng sử dụng linh cốt Ngũ Sắc Khổng Tước để luyện chế Tu Di Động Thiên Đồ.","trangThai":"Ba Tu Di Động Thiên Đồ có tỳ vết đã thất lạc ra ngoài tộc.","capNhatToi":"@c1422","tabs":{"tienTrinh":[{"chuong":"@c1422","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ lịch sử luyện bảo","text":"Lịch sử Ngũ Quang Tộc luyện chế mười Tu Di Động Thiên Đồ và để thất lạc ba phế phẩm có tỳ vết được tiết lộ.","anchor":"ngũ quang tộc sử dụng linh cốt của ngũ sắc không tước luyện chế","trangThaiMoc":"Ba phế phẩm có tỳ vết đã thất lạc"}]},"nguon":["@c1422","@c1430","@c1851"]},{"id":"bi-thuc-toc","name":"Bị Thức tộc","cn":"","type":"chung-toc","typeLabel":"Phân tộc Phi Linh","diaBan":"Lãnh địa Phi Linh tộc","nhanVatChinh":["Thanh niên áo bào đen có sừng và nanh"],"blurb":"Một phân tộc của Phi Linh tộc, sở hữu Thiên chung giáng Ma thần thông.","detail":"Thanh niên áo đen thuộc Bị Thức tộc sử dụng thần thông của tộc để đánh bại nam tử hóa hạc trong cuộc tỷ thí gần Ngọc Hoàng Đỉnh.","nguon":["@c1430"]},{"id":"thien-man-toc","name":"Thiên Man tộc","cn":"","type":"chung-toc","typeLabel":"Phân tộc Phi Linh","diaBan":"Lãnh địa Phi Linh tộc","nhanVatChinh":[],"blurb":"Một phân tộc Phi Linh có thánh tử đến khu vực Ngọc Hoàng Đỉnh dự thịnh hội.","detail":"Danh tiếng của Thiên Man tộc khiến thanh niên Bị Thức tộc ngừng khiêu chiến và hạ xuống ngay khi nghe tin thánh tử của tộc đã tới.","nguon":["@c1430"]},{"id":"o-linh-toc","name":"Ô Linh tộc","cn":"","type":"chung-toc","typeLabel":"Phân tộc Phi Linh","diaBan":"Lãnh địa Phi Linh tộc","nhanVatChinh":[],"blurb":"Một phân tộc Phi Linh được nhắc đến trong cuộc tranh luận về lịch sử của Thiên Bằng tộc.","detail":"Chúc trưởng lão nhắc Ô Linh tộc trong mối liên hệ với nguồn gốc của Thạch trưởng lão.","nguon":["@c1430"]},{"id":"dieu-linh-toc","name":"Điểu Linh tộc","cn":"","type":"chung-toc","typeLabel":"Phân tộc Phi Linh","diaBan":"Lãnh địa Phi Linh tộc","nhanVatChinh":[],"blurb":"Một phân tộc từng giữ địa vị thánh chủ của các tộc theo lời Kim Duyệt.","detail":"Điểu Linh tộc từng bị đối thủ chèn ép và chủ động xin gia nhập Thiên Bằng tộc. Chương chưa xác nhận Điểu Linh tộc và Ô Linh tộc là cùng một tộc.","nguon":["@c1430"]},{"id":"cuu-viet-toc","name":"Cửu Việt tộc","cn":"","type":"chung-toc","typeLabel":"Phân tộc Phi Linh","diaBan":"Lãnh địa Phi Linh tộc","nhanVatChinh":[],"blurb":"Một phân tộc Phi Linh được nhắc đến trong nghi vấn về mục tiêu của Xích Dung tộc.","detail":"Thu phu nhân nghi ngờ việc Xích Dung tộc muốn thâu tóm Thiên Bằng tộc có thể nhằm đàn áp Cửu Việt tộc, nhưng Chúc trưởng lão phủ nhận.","nguon":["@c1430"]},{"id":"quy-dien-toc","name":"Quỷ Diện tộc","cn":"","type":"chung-toc","typeLabel":"Phân tộc Phi Linh","diaBan":"Phía bắc lãnh địa Phi Linh tộc","nhanVatChinh":[],"blurb":"Một phân tộc Phi Linh vắng mặt khi thịnh hội tại Ngọc Hoàng Đỉnh bắt đầu.","detail":"Quỷ Diện tộc có việc quan trọng ở phía bắc và phải đợi Địa Uyên mở ra mới có thể đến dự thịnh hội.","nguon":["@c1430"]},{"id":"doc-cuu-toc","name":"Độc Cưu tộc","cn":"","type":"chung-toc","typeLabel":"Phân tộc Phi Linh","diaBan":"Phía bắc lãnh địa Phi Linh tộc","nhanVatChinh":[],"blurb":"Một phân tộc Phi Linh chưa đến Ngọc Hoàng Đỉnh vào lúc thịnh hội bắt đầu.","detail":"Độc Cưu tộc cùng Quỷ Diện tộc phải đợi Địa Uyên mở ra mới có thể khởi hành đến dự hội.","nguon":["@c1430"]},{"id":"uyen-thu-ve","name":"Uyên thủ vệ","cn":"","type":"quân lực","typeLabel":"Lực lượng trấn giữ","diaBan":"Địa Uyên","nhanVatChinh":["Kim Trác"],"blurb":"Lực lượng Phi Linh tộc trấn giữ Địa Uyên, mặc chiến giáp do sát khí ngưng tụ. Đội quân hiện diện có hàng vạn thành viên và nhiều tu sĩ cao giai.","detail":"Uyên thủ vệ hành động chỉnh tề, có tu vi trải từ ngoài Kết Đan đến Nguyên Anh, Hóa Thần và Luyện Hư. Hàn Lập đánh giá lực lượng này tinh nhuệ hơn quân trú đóng tại Thiên Uyên thành và cho rằng vẫn có thể còn quân lực chưa xuất hiện.","quyMo":"Hàng vạn người hiện diện","caoThuManhNhat":"Có thành viên cấp Luyện Hư","soCaoThu":"Nhiều tu sĩ Nguyên Anh, Hóa Thần và không ít tu sĩ Luyện Hư","trangThai":"Trấn giữ Địa Uyên","thanhVien":[{"ten":"Kim Trác","chucVu":"Người chỉ huy phát tín hiệu mở đường","tuChuong":"@c1435","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1435","tabs":{"tienTrinh":[{"chuong":"@c1435","loai":"nhắc tới","importance":"normal","giaiDoan":"Đón đoàn thí luyện","text":"Uyên thủ vệ tập kết bên ngoài Địa Uyên và theo tín hiệu của Kim Trác tách thành hai hàng để mở đường cho các đoàn dự thí luyện.","anchor":"Ngoài ra những tồn tại tương đương với Nguyên Anh hay Hóa thần thì chỗ nào cũng có, thậm chí luyện hư cấp bậc cũng không phải là ít."}]},"nguon":["@c1435"]},{"id":"thien-hat-toc","name":"Thiên Hạt Tộc","cn":"","aliases":[],"type":"chủng tộc","typeLabel":"Phi Linh chi tộc","diaBan":"Địa Uyên","nhanVatChinh":[],"blurb":"Một nhánh tham gia Địa Uyên thí luyện và có thái độ bất thiện với nhóm Hàn Lập.","detail":"Để tránh các nhánh Thiên Hạt Tộc đang có ác ý và gây khó khăn cho việc truy dấu, Hàn Lập chủ động dẫn đội tới cửa xuống tầng hai xa nhất.","trangThai":"Đang tham gia Địa Uyên thí luyện","capNhatToi":"@c1441","nguon":["@c1441"]},{"id":"da-luc-toc","name":"Dạ Lục Tộc","cn":"","type":"chung-toc","typeLabel":"Nhánh Phi Linh Tộc","diaBan":"Chưa rõ","nhanVatChinh":["Tần Hiểu"],"blurb":"Một nhánh của Phi Linh Tộc có minh ước hỗ trợ lẫn nhau với Thiên Bằng Tộc.","detail":"Thánh tử Tần Hiểu của Dạ Lục Tộc viện dẫn minh ước với Thiên Bằng Tộc để cầu nhóm Hàn Lập trợ giúp khi bị Hoàng Phong Tộc truy sát.","quanHe":"Có minh ước hỗ trợ lẫn nhau với Thiên Bằng Tộc.","thanhVien":[{"ten":"Tần Hiểu","chucVu":"Thánh tử","tuChuong":"@c1445","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1445","loai":"nhắc tới","importance":"normal","giaiDoan":"Thành viên bị truy sát","text":"Tần Hiểu dựa vào minh ước giữa Dạ Lục Tộc và Thiên Bằng Tộc để cầu cứu khi bị Hoàng Phong Tộc truy sát.","anchor":"hai tộc chúng ta có minh ước hỗ trợ lẫn nhau","trangThaiMoc":"Có thành viên tham gia thí luyện"}]},"capNhatToi":"@c1445","nguon":["@c1445"]},{"id":"hoang-phong-toc","name":"Hoàng Phong Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Không rõ","nhanVatChinh":["Ba thánh tử Hoàng Phong Tộc truy đuổi Tần Hiểu","Ba thánh tử Hoàng Phong Tộc cưỡi mộc điểu"],"blurb":"Một phân chi Phi Linh Tộc có người truy sát Tần Hiểu trong nhiều ngày.","detail":"Tần Hiểu cho rằng người Hoàng Phong Tộc truy sát mình nhằm đoạt Hỗn Nguyên Hồ.","quanHe":"Đối địch với Tần Hiểu và Dạ Lục Tộc trong cuộc truy sát.","trangThai":"Đang truy sát Tần Hiểu","capNhatToi":"@c1446","tabs":{"tienTrinh":[{"chuong":"@c1446","loai":"khai chiến","importance":"normal","giaiDoan":"Truy sát Tần Hiểu","trangThaiMoc":"Đang truy sát","text":"Người Hoàng Phong Tộc truy sát Tần Hiểu đến tận khu vực nàng gặp nhóm Hàn Lập.","anchor":"Nhưng không nghĩ tới trên đường lại gặp người của Hoàng Phong Tộc, bị đuổi giết đến tận đây."}]},"nguon":["@c1446"]},{"id":"that-viet-toc","name":"Thất Việt Tộc","cn":"","type":"phân chi","typeLabel":"Phân chi Phi Linh Tộc","diaBan":"Không rõ","nhanVatChinh":["Ngao Thanh","Kiều Thanh"],"blurb":"Một phân chi của Phi Linh Tộc có truyền thống lấy thực lực làm tiêu chuẩn quan trọng trong việc hôn phối của thánh tử.","detail":"Thánh tử Thất Việt Tộc, bất kể nam hay nữ, lựa chọn người kết đôi dựa trên thực lực của các phân chi. Lễ trưởng thành của Ngao Thanh sẽ diễn ra sau ba năm và nàng phải quyết định chuyện hôn phối vào thời điểm đó.","tonChi":"Thánh tử lựa chọn người kết đôi dựa trên thực lực của các phân chi.","thanhVien":[{"ten":"Ngao Thanh","chucVu":"Thánh tử","tuChuong":"@c1447","trangThai":"đang hoạt động"},{"ten":"Kiều Thanh","chucVu":"Thánh tử","tuChuong":"@c1447","trangThai":"đang hoạt động"}],"trangThai":"đang tồn tại","capNhatToi":"@c1447","tabs":{"tienTrinh":[{"chuong":"@c1447","loai":"nhắc tới","importance":"bridge","giaiDoan":"Tiêu chuẩn hôn phối","text":"Ngao Thanh giải thích rằng thánh tử Thất Việt Tộc lựa chọn người kết đôi dựa trên thực lực của các phân chi.","anchor":"thánh tử Thất Việt Tộc chúng ta, vô luận là nam hay nữ cũng chỉ lấy thực lực cường đại của các phân chi làm thước đo","trangThaiMoc":"đang tồn tại"}]},"nguon":["@c1447"]},{"id":"nam-lung-toc","name":"Nam Lũng Tộc","cn":"","type":"phân chi","typeLabel":"Phân chi Phi Linh Tộc","diaBan":"Không rõ","nhanVatChinh":["Phí Dạ"],"blurb":"Phân chi Phi Linh Tộc mà Phí Dạ trực thuộc.","detail":"Phí Dạ là thánh tử thuộc Nam Lũng Tộc và tham gia thí luyện Địa Uyên.","thanhVien":[{"ten":"Phí Dạ","chucVu":"Thánh tử","tuChuong":"@c1447","trangThai":"đang hoạt động"}],"trangThai":"đang tồn tại","capNhatToi":"@c1447","nguon":["@c1447"]},{"id":"huyet-giao","name":"Huyết Giao","cn":"","aliases":[],"type":"yeu-vat","typeLabel":"Lực lượng yêu vật","diaBan":"Tầng ba Địa Uyên","nhanVatChinh":["Mộc Thanh","Huyết Độc"],"blurb":"Lực lượng yêu vật dưới quyền Mộc Thanh, có thành viên đạt cấp Linh Suất kỳ.","detail":"Địa Huyết dùng linh mộc làm giá để mượn lực lượng Huyết Giao truy sát nhóm Phi Linh tộc. Mộc Thanh phái Huyết Độc lên tầng hai thực hiện nhiệm vụ.","lanhDaoHienThoi":"Mộc Thanh","thanhVien":[{"ten":"Mộc Thanh","chucVu":"Chủ nhân","tuChuong":"@c1452","trangThai":"Đang lãnh đạo"},{"ten":"Huyết Độc","chucVu":"Thuộc hạ","tuChuong":"@c1452","trangThai":"Đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1452","loai":"khai chiến","importance":"normal","giaiDoan":"Nhận nhiệm vụ truy sát","text":"Mộc Thanh điều Huyết Độc thuộc lực lượng Huyết Giao lên tầng hai truy sát nhóm Phi Linh tộc.","anchor":"Ta sẽ đem Huyết Giao trực tiếp đưa lên tầng hai, ba ngày sau sẽ có tin truyền về"}]},"capNhatToi":"@c1452","nguon":["@c1452"]},{"id":"hac-linh-toc","name":"Hắc Linh tộc","cn":"","type":"phan-chi","typeLabel":"Phân chi Phi Linh tộc","diaBan":"Không rõ","nhanVatChinh":["Thủ lĩnh Hắc Linh tộc","Sáu người Hắc Linh tộc"],"blurb":"Một phân chi có thứ hạng hàng đầu trong bảy mươi hai phân chi Phi Linh tộc.","detail":"Một đội bảy người Hắc Linh tộc nhận lợi ích từ các phân chi Xích Dung tộc để chặn giết nhóm thánh tử Thiên Bằng tộc tại Địa Uyên. Đội này dùng Kim Ô Linh Hỏa và Hắc Sắc Linh Vũ làm thủ đoạn hợp kích.","quyMo":"Thuộc nhóm đầu trong bảy mươi hai phân chi.","quanHe":"Nhận lời từ các phân chi Xích Dung tộc để đối phó Thiên Bằng tộc.","trangThai":"Đang tham gia thí luyện tại Địa Uyên","thanhVien":[{"ten":"Thủ lĩnh Hắc Linh tộc","chucVu":"Thủ lĩnh đội bảy người","tuChuong":"@c1453","trangThai":"không rõ"},{"ten":"Sáu người Hắc Linh tộc","chucVu":"Thành viên đội phục kích","tuChuong":"@c1453","trangThai":"đang hoạt động"}],"capNhatToi":"@c1453","tabs":{"tienTrinh":[{"chuong":"@c1453","loai":"khai chiến","importance":"normal","giaiDoan":"Phục kích Thiên Bằng tộc","text":"Đội bảy người Hắc Linh tộc nhận lợi ích từ các phân chi Xích Dung tộc và dùng Kim Ô Linh Hỏa phục kích nhóm Hàn Lập.","anchor":"Hắc Linh tộc trong bảy mươi hai phân chi cũng bài danh nhóm đầu, vượt xa Thiên Bằng tộc là phân chi yếu kém.","trangThaiMoc":"Đội phục kích bị Hàn Lập phá hợp kích"}]},"nguon":["@c1453"]},{"id":"ta-long-toc","name":"Tà Long Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Linh giới thời thượng cổ","nhanVatChinh":["Hắc Uyên ngạc"],"blurb":"Một chủng tộc cổ xưa được cho là đã tuyệt tích tại Linh giới. Tiểu Ngạc được xác nhận là hậu duệ còn tồn tại của tộc này. (+) Chủng tộc từng xưng bá Linh giới vào thời thượng cổ và tiến hành hủy diệt Kim Lôi Trúc. [CAN-SOAT-GOP]","detail":"Tà Long Tộc gần như hủy sạch Kim Lôi Trúc tại Linh giới, đồng thời giết những người tu luyện hoặc nắm giữ loại linh trúc này.","nguonGoc":"Linh giới","quyMo":"Từng xưng bá Linh giới thời thượng cổ","quanHe":"Đối địch với những người tu luyện hoặc sở hữu Kim Lôi Trúc","trangThai":"Không rõ ở thời điểm hiện tại","tabs":{"tienTrinh":[{"chuong":"@c1459","loai":"nhắc tới","importance":"normal","giaiDoan":"Thời thượng cổ","text":"Tà Long Tộc được nhắc là thế lực từng hủy gần hết Kim Lôi Trúc và truy sát những người có liên quan.","anchor":"những kẻ tu luyện và giữ Kim Lôi Trúc cũng bị giết sạch","trangThaiMoc":"Từng xưng bá Linh giới"},{"chuong":"@c1653","loai":"nhắc tới","importance":"bridge","giaiDoan":"Hé lộ tiềm lực huyết mạch","text":"Hoa đại nhân nhắc đến tiềm lực của Tà Long tộc khi đánh giá chân huyết trong cơ thể Hắc Uyên ngạc.","anchor":"Ngươi trong Tà long tộc có thể trực tiếp cắn nuốt được Thiên ngoại ma đầu","trangThaiMoc":"được nhắc tới"}]},"capNhatToi":"@c1459","nguon":["@c1459","@c1653","@c1873"],"thanhVien":[{"ten":"Hắc Uyên ngạc","chucVu":"","tuChuong":"@c1653","trangThai":"đã khai mở chân huyết"},{"ten":"Tiểu Ngạc","chucVu":"Hậu duệ","tuChuong":"@c1873","trangThai":"Còn sống"}]},{"id":"moc-tien-coc","name":"Mộc Tiên Cốc","cn":"","type":"dia-phuong-the-luc","typeLabel":"Thế lực địa phương","diaBan":"Hắc Vụ Lâm, tầng ba Địa Uyên","nhanVatChinh":["Mộc Thanh","Huyết Độc","Bích Nhi"],"blurb":"Thế lực và địa bàn dưới quyền Mộc Thanh tại Hắc Vụ Lâm. Huyết Độc thay mặt nơi này mời Hàn Lập ở lại và hứa cung cấp tài nguyên tu luyện.","detail":"Mộc Tiên Cốc nằm trong Hắc Vụ Lâm thuộc tầng ba Địa Uyên. Mộc Thanh là chủ nhân, còn Huyết Độc và Bích Nhi phục vụ dưới quyền nàng.","nguonGoc":"Hắc Vụ Lâm tại tầng ba Địa Uyên","lanhDaoHienThoi":"Mộc Thanh","quanHe":"Tham gia kế hoạch tiến vào Minh Hà Chi Địa","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Mộc Thanh","chucVu":"Chủ nhân","tuChuong":"@c1459","trangThai":"đang tại vị"},{"ten":"Huyết Độc","chucVu":"Thuộc hạ","tuChuong":"@c1459","trangThai":"đang phục vụ"},{"ten":"Bích Nhi","chucVu":"Thị nữ","tuChuong":"@c1459","trangThai":"đang phục vụ"}],"lanhDaoMoc":[{"ten":"Mộc Thanh","tuChuong":"@c1459","denChuong":""}],"tabs":{"tienTrinh":[{"chuong":"@c1459","loai":"nhắc tới","importance":"normal","giaiDoan":"Mời Hàn Lập lưu lại","text":"Huyết Độc thay mặt Mộc Tiên Cốc thuyết phục Hàn Lập ở lại và hứa cung cấp tài nguyên tu luyện cho hắn.","anchor":"Hàn huynh đệ cứ yên tâm ở lại Mộc Tiên Cốc chúng ta","trangThaiMoc":"Đang hoạt động"}]},"capNhatToi":"@c1459","nguon":["@c1459"]},{"id":"tu-dai-yeu-vuong-dia-uyen","name":"Tứ Đại Yêu Vương Địa Uyên","cn":"","type":"lien-minh","typeLabel":"Liên minh yêu vương","diaBan":"Địa Uyên","nhanVatChinh":["Lục Túc","Mộc Thanh","Lam đạo hữu","Địa Huyết","Mỹ phụ tóc bạc"],"blurb":"Bốn yêu vương Hợp Thể Kỳ tại Địa Uyên cùng chuẩn bị kế hoạch công phá Minh Hà cấm chế.","detail":"Lục Túc, Mộc Thanh, Lam đạo hữu và Địa Huyết xác nhận giá trị của Ích Tà Thần Lôi do Hàn Lập nắm giữ, phân chia lịch huấn luyện hắn trong sáu năm và cùng đặt tiêu ký để ngăn hắn đào thoát.","lanhDaoHienThoi":"Lục Túc giữ vai trò định đoạt trong cuộc thương nghị","caoThuManhNhat":"Bốn yêu vương Hợp Thể Kỳ","soCaoThu":"Bốn yêu vương Hợp Thể Kỳ","quanHe":"Cùng hợp tác trong kế hoạch phá Minh Hà cấm chế.","trangThai":"Đang mở đường tiến vào Minh Hà Chi Địa","thanhVien":[{"ten":"Lục Túc","chucVu":"Yêu vương chỉ huy nhóm tiên phong","tuChuong":"@c1461","trangThai":"đang hoạt động"},{"ten":"Mộc Thanh","chucVu":"Yêu vương phụ trách huyết cầu dẫn ma","tuChuong":"@c1461","trangThai":"đang hoạt động"},{"ten":"Lam đạo hữu","chucVu":"Yêu vương","tuChuong":"@c1461","trangThai":"Đang tham gia"},{"ten":"Địa Huyết","chucVu":"Yêu vương","tuChuong":"@c1461","trangThai":"đang hoạt động"},{"ten":"Mỹ phụ tóc bạc","chucVu":"Yêu vương","tuChuong":"@c1474","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1461","loai":"liên minh","importance":"normal","giaiDoan":"Khống chế Hàn Lập","text":"Bốn yêu vương thống nhất lịch huấn luyện Hàn Lập trong sáu năm và cùng đặt tiêu ký lên người hắn để phục vụ kế hoạch công phá Minh Hà cấm chế.","anchor":"Trước mặt bốn gã yêu vương Hợp Thể Kỳ, Hàn Lập đích xác không có quyền nói chuyện","trangThaiMoc":"Đang hợp tác"},{"chuong":"@c1474","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Khởi động hành trình Minh Hà","text":"Các yêu vương dùng Kinh Không Ma mở thông đạo, cử Lục Túc và Mộc Thanh đi trước để đả thông đường cho đại quân tiến vào Minh Hà Chi Địa.","anchor":"Mộc đạo hữu và ta đi vào trước để đả thong không gian giao tiếp với Minh Hà Chi Địa","trangThaiMoc":"Đang mở thông đạo"}]},"capNhatToi":"@c1461","nguon":["@c1461","@c1474"]},{"id":"khap-ba-cong-co-dai-toc","name":"Khấp Bá Công cổ đại tộc","cn":"","type":"co-dai-toc","typeLabel":"Nhóm cổ đại tộc","diaBan":"Linh giới","nhanVatChinh":[],"blurb":"Khấp Bá Công cổ đại tộc là một trong các cổ đại tộc từng áp bức những chủng tộc khác tại Linh giới. Sau đó, họ bị phần lớn các chủng tộc ở Linh giới liên thủ tiêu diệt.","detail":"Khấp Bá Công cổ đại tộc từng áp bức các chủng tộc khác tại Linh giới. Hành động này khiến phần lớn các chủng tộc liên thủ chống lại và cuối cùng tiêu diệt họ. @c1462","trangThai":"Đã bị tiêu diệt","capNhatToi":"@c1462","tabs":{"tienTrinh":[{"chuong":"@c1462","loai":"diệt/sáp nhập","importance":"major","giaiDoan":"Bị liên quân tiêu diệt","text":"Các cổ đại tộc bị phần lớn chủng tộc tại Linh giới liên thủ tiêu diệt sau thời gian áp bức những tộc khác.","anchor":"cuối cùng bị phần lớn chủng tộc liên thủ tiêu diệt","trangThaiMoc":"Đã bị tiêu diệt"}]},"nguon":["@c1462"],"dacDiem":"Một cổ đại tộc từng áp bức các chủng tộc khác tại Linh giới và đã bị liên quân của phần lớn các tộc tiêu diệt. @c1462"},{"id":"thuoc-ha-huyet-diem-cung","name":"Thuộc hạ Huyết Diễm Cung","cn":"","type":"thuoc-ha","typeLabel":"Lực lượng canh giữ","diaBan":"Huyết Diễm Cung","nhanVatChinh":["Huyết bào nhân","Hai đội người canh Huyết Diễm Cung"],"blurb":"Lực lượng thuộc hạ canh giữ Huyết Diễm Cung và phục tùng Huyết bào nhân.","detail":"Lực lượng này gồm ít nhất hai đội sinh linh có khí tức sinh mệnh: một đội mặc hồng giáp cầm hỏa qua và một đội ẩn trong sương xám. Họ im lặng thi lễ, chấp hành mệnh lệnh và mở Âm Hỏa Điện.","lanhDaoHienThoi":"Huyết bào nhân","quyMo":"Ít nhất hai đội canh giữ","quanHe":"Phục tùng Huyết bào nhân","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Hai đội người canh Huyết Diễm Cung","chucVu":"Canh giữ cung điện","tuChuong":"@c1465","trangThai":"đang hoạt động"}],"lanhDaoMoc":[{"ten":"Huyết bào nhân","tuChuong":"@c1465","denChuong":""}],"capNhatToi":"@c1465","tabs":{"tienTrinh":[{"chuong":"@c1465","loai":"xuất hiện","importance":"normal","giaiDoan":"Nghênh đón khách","text":"Hai đội thuộc hạ ra nghênh đón nhóm Hàn Lập, thi lễ với hai huyết bào nhân và mở Âm Hỏa Điện theo lệnh.","anchor":"Hai đội cổ quái này đi đến, lập tức thi lễ với hai gã huyết bào nhân."}]},"nguon":["@c1465"]},{"id":"doi-quan-tien-phong-pha-minh-ha","name":"Đội quân tiên phong phá Minh Hà","cn":"","type":"quan-doi","typeLabel":"Quân đội","diaBan":"Thông đạo Minh Hà","nhanVatChinh":["Lục Túc"],"blurb":"Gần vạn đơn vị gồm khôi lỗi, quỷ binh, yêu thú và yêu vật được tổ chức thành đội hình tiên phong tiến vào thông đạo Minh Hà thăm dò nguy hiểm.","detail":"Theo mệnh lệnh các yêu vương, đội hình bố trí khôi lỗi cùng Âm giáp huyền quỷ ở hai cánh, gần vạn đê giai yêu vật kẹp ở giữa, rồi bị phái tiến vào thông đạo trước để thăm dò. Khi vừa vào, vô số tơ bạc bắn ra chỉ nhắm đám đê giai yêu vật ở giữa, hoàn toàn bỏ qua khôi lỗi và huyền quỷ hai bên.","quyMo":"Gần vạn","nguonGoc":"Do Tứ đại yêu vương Địa Uyên tổ chức","trangThai":"dang hoat dong","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1476","loai":"lap","importance":"normal","giaiDoan":"Tiến vào thông đạo","trangThaiMoc":"dang hoat dong","text":"Gần vạn yêu thú và yêu vật cùng khôi lỗi, huyền quỷ được phái vào thông đạo Minh Hà thăm dò. Tơ bạc lập tức tập kích có chọn lọc.","anchor":"Số lượng đạt đến gần vạn, gần như lèn chật cứng cái thông đạo!"}]},"capNhatToi":"@c1476","nguon":["@c1476"]},{"id":"dao-quan-quy-binh","name":"Đạo quân quỷ binh","cn":"","type":"quan-doi","typeLabel":"Thế lực quân sự","diaBan":"Chiến trường ngoài quỷ vụ","nhanVatChinh":[],"blurb":"Đạo quân gồm mấy nghìn quỷ binh đứng theo trận thế chỉnh tề.","detail":"Lực lượng quỷ binh tỏa sát khí và âm phong, đang giằng co với đạo quân huyết giáp tại khoảng không bên ngoài quỷ vụ.","quyMo":"Mấy nghìn quỷ binh","quanHe":"Đối trận với đạo quân huyết giáp","trangThai":"Đang giằng co trên chiến trường","capNhatToi":"@c1481","tabs":{"tienTrinh":[{"chuong":"@c1481","loai":"khai chiến","importance":"normal","giaiDoan":"Đối trận huyết giáp quân","text":"Mấy nghìn quỷ binh xếp thành trận thế và giằng co với đạo quân huyết giáp.","anchor":"tại phía xa hơn là mấy ngàn quỷ binh đứng theo trận thế vô cùng chỉnh tế","trangThaiMoc":"Đang đối trận"}]},"nguon":["@c1481"]},{"id":"dao-quan-huyet-giap","name":"Đạo quân huyết giáp","cn":"","type":"quan-doi","typeLabel":"Thế lực quân sự","diaBan":"Chiến trường ngoài quỷ vụ","nhanVatChinh":["Võ tướng mặc tử giáp","Hai võ tướng còn lại"],"blurb":"Đạo quân tinh nhuệ gồm khoảng bảy tám nghìn giáp sĩ cao lớn và hơn hai trăm chiến xa.","detail":"Các giáp sĩ cao khoảng hai trượng, được trang bị đầy đủ binh khí và tổ chức thành lực lượng có huấn luyện bài bản. Đạo quân đang giằng co với quỷ binh và đội ngũ phía Mộc Thanh.","quyMo":"Khoảng bảy tám nghìn giáp sĩ và hơn hai trăm chiến xa","capBac":"Quân tinh nhuệ","quanHe":"Đối đầu đạo quân quỷ binh và đội ngũ Mộc Thanh","trangThai":"Đang giằng co trên chiến trường","thanhVien":[{"ten":"Võ tướng mặc tử giáp","chucVu":"Võ tướng","tuChuong":"@c1481","trangThai":"Đang hoạt động"},{"ten":"Hai võ tướng còn lại","chucVu":"Võ tướng","tuChuong":"@c1481","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1481","tabs":{"tienTrinh":[{"chuong":"@c1481","loai":"khai chiến","importance":"normal","giaiDoan":"Giằng co ngoài quỷ vụ","text":"Đạo quân huyết giáp triển khai đông đảo giáp sĩ và chiến xa để đối đầu lực lượng phía bên kia.","anchor":"Vừa nhìn là đã biết đây là một nhóm quân tinh nhuệ có huấn luyện bài bản","trangThaiMoc":"Đang đối trận"}]},"nguon":["@c1481"]},{"id":"doi-ngu-moc-thanh-va-my-phu-dau-bac","name":"Đội ngũ Mộc Thanh và mỹ phụ đầu bạc","cn":"","type":"nhom","typeLabel":"Nhóm yêu vật","diaBan":"Chiến trường ngoài quỷ vụ","nhanVatChinh":["Mộc Thanh","Mỹ phụ đầu bạc","Tám Âm giáp Quỷ Vương"],"blurb":"Đội ngũ do Mộc Thanh và mỹ phụ đầu bạc dẫn đầu, gồm hơn mười yêu vật cấp cao cùng tám âm giáp quỷ binh.","detail":"Nhóm đứng trên cao đối diện ba võ tướng và lực lượng huyết giáp. Quan hệ tổ chức cụ thể giữa toàn bộ thành viên chưa được xác định.","quyMo":"Hơn mười yêu vật cấp cao và tám âm giáp quỷ binh","quanHe":"Đối đầu ba võ tướng và đạo quân huyết giáp","trangThai":"Đang giằng co trên chiến trường","thanhVien":[{"ten":"Mộc Thanh","chucVu":"Người dẫn đầu","tuChuong":"@c1481","trangThai":"Đang hoạt động"},{"ten":"Mỹ phụ đầu bạc","chucVu":"Người dẫn đầu","tuChuong":"@c1481","trangThai":"Đang hoạt động"},{"ten":"Tám Âm giáp Quỷ Vương","chucVu":"Lực lượng đi theo","tuChuong":"@c1481","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1481","tabs":{"tienTrinh":[{"chuong":"@c1481","loai":"khai chiến","importance":"normal","giaiDoan":"Đối đầu ba võ tướng","text":"Mộc Thanh và mỹ phụ đầu bạc dẫn yêu vật cấp cao cùng tám âm giáp quỷ binh đối diện ba võ tướng.","anchor":"phía sau bọn họ còn có hơn mười yêu vật cấp cao và tám gã âm giáp quỷ binh","trangThaiMoc":"Đang đối trận"}]},"nguon":["@c1481"]},{"id":"phu-du-toc","name":"Phù Du Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Minh Hà Chi Địa theo lời tử giáp võ tướng","nhanVatChinh":["Tử giáp võ tướng","Khôi lỗi võ tướng ba mắt","Khôi lỗi võ tướng hai đầu bốn tay","Lục Túc","Huyết giáp khôi lỗi","Khương tiền bối"],"blurb":"Phù Du Tộc là một chủng tộc coi Minh Hà là thánh địa và sở hữu khoảng một nửa lượng Minh Hà thần nhũ. Tộc điều động các võ tướng khôi lỗi cùng lực lượng hộ vệ để ngăn chặn người xâm nhập, đồng thời từng tuyên bố sẽ truy sát nhóm Mộc Thanh trên toàn Linh giới nếu họ đoạt thánh vật rồi đào thoát.","detail":"Phù Du Tộc bảo vệ Minh Hà như thánh địa có chứa thánh vật của tộc. Khi nhóm Mộc Thanh xâm nhập, các võ tướng khôi lỗi của Phù Du Tộc tuyên bố khai chiến để bảo vệ nơi này; lực lượng xuất hiện gồm ba võ tướng khôi lỗi, huyết giáp khôi lỗi và các quái thú kéo xe @c1482. Tử giáp võ tướng còn tuyên bố Phù Du Tộc sẽ truy sát nhóm Mộc Thanh trên toàn Linh giới nếu họ đoạt thánh vật rồi chạy thoát. Lục Túc vốn xuất thân từ Phù Du Tộc @c1485. Một thái thượng trưởng lão của tộc có giao tình với Thanh Nguyên Tử. Huyết giáp khôi lỗi từng xin tiếp dẫn bản thể mang Thần Sào tới Minh Hà chi địa @c1506.","tonChi":"Bảo vệ thánh địa và thánh vật trong Minh Hà","tranPhai":"Thánh vật trong Minh Hà","trangThai":"Thần nhũ bị người ngoại lai đoạt","thanhVien":[{"ten":"Tử giáp võ tướng","chucVu":"Võ tướng chỉ huy","tuChuong":"@c1482","trangThai":"đang hoạt động"},{"ten":"Khôi lỗi võ tướng ba mắt","chucVu":"Võ tướng","tuChuong":"@c1482","trangThai":"đang hoạt động"},{"ten":"Khôi lỗi võ tướng hai đầu bốn tay","chucVu":"Võ tướng","tuChuong":"@c1482","trangThai":"đang hoạt động"},{"ten":"Lục Túc","chucVu":"Nguyên thành viên","tuChuong":"@c1485","trangThai":"đã rời"},{"ten":"Huyết giáp khôi lỗi","chucVu":"Sứ giả","tuChuong":"@c1506","trangThai":"Đang truy tìm người đoạt thần nhũ"},{"ten":"Thái thượng trưởng lão Phù du tộc","chucVu":"Thái thượng trưởng lão","tuChuong":"@c1858","trangThai":"Không rõ"}],"quanHe":"Đối địch với nhóm Mộc Thanh và mỹ phụ đầu bạc","capNhatToi":"@c1482","tabs":{"tienTrinh":[{"chuong":"@c1482","loai":"khai chiến","importance":"normal","giaiDoan":"Bảo vệ thánh địa","trangThaiMoc":"Giao chiến với lực lượng xâm nhập","text":"Các võ tướng khôi lỗi của Phù Du Tộc tuyên bố bảo vệ thánh địa và khai chiến với nhóm Mộc Thanh.","anchor":"bổn tộc cũng sẽ phái người truy giết các ngươi trên toàn Linh giới"},{"chuong":"@c1485","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ quan hệ","text":"Lục Túc thừa nhận mình vốn xuất thân từ Phù Du tộc, trong khi đặc điểm thánh địa và sức mạnh của bộ tộc này được hé lộ.","anchor":"Nguyên bản ta xuất thân từ bộ tộc này."},{"chuong":"@c1506","loai":"nhắc tới","importance":"normal","giaiDoan":"Chuẩn bị tăng viện","trangThaiMoc":"Thần nhũ bị đoạt và bản thể huyết giáp khôi lỗi được đề nghị tiếp dẫn","text":"Huyết giáp khôi lỗi xin tiếp dẫn bản thể mang Thần Sào tới Minh Hà chi địa, dù người Phù Du Tộc sẽ bị âm khí xâm thực và suy giảm tu vi.","anchor":"các ngươi sẽ bị âm khí xâm thực mà đại giảm tu vị"}]},"nguon":["@c1482","@c1485","@c1506","@c1858","@c1870"],"uyLuc":"Phù Du Tộc có thể triển khai nhiều võ tướng khôi lỗi, huyết giáp khôi lỗi và quái thú kéo xe để bảo vệ Minh Hà, đồng thời tuyên bố đủ khả năng truy sát kẻ đoạt thánh vật trên toàn Linh giới.","dacDiem":"Coi Minh Hà là thánh địa chứa thánh vật của tộc; lực lượng hộ vệ nổi bật bởi các khôi lỗi được phân hồn điều khiển.","congNang":["Điều động phân hồn phụ vào khôi lỗi để bảo vệ thánh địa và giao chiến với người xâm nhập @c1482.","Nắm giữ khoảng một nửa lượng Minh Hà thần nhũ."]},{"id":"am-giap-quy-binh","name":"Âm giáp quỷ binh","cn":"","type":"quan-doi","typeLabel":"Quân đoàn quỷ binh","diaBan":"Minh Hà Chi Địa","nhanVatChinh":["Mỹ phụ đầu bạc","Tám Âm giáp Quỷ Vương"],"blurb":"Đội quân quỷ binh do mỹ phụ đầu bạc bồi dưỡng, lấy tám quỷ vương làm đầu lĩnh.","detail":"Âm giáp quỷ binh có năng lực cá thể vượt trội quân đoàn huyết giáp khôi lỗi và giành thượng phong trong giao chiến. Đội quân cũng mất gần một nửa lực lượng, còn những cá thể mắc kẹt bị phong bạo tiêu diệt.","quyMo":"Quân đoàn quỷ binh cùng tám quỷ vương @c1483","thanhVien":[{"ten":"Tám Âm giáp Quỷ Vương","chucVu":"Đầu lĩnh","tuChuong":"@c1483","trangThai":"dang-hoat-dong"}],"trangThai":"Tổn thất gần một nửa lực lượng @c1483","tabs":{"tienTrinh":[{"chuong":"@c1483","loai":"suy","importance":"normal","giaiDoan":"Tổn thất trong phong bạo","text":"Âm giáp quỷ binh đánh lui quân đoàn khôi lỗi nhưng mất gần một nửa lực lượng và tiếp tục bị phong bạo tàn phá.","anchor":"mà âm giáp quỷ binh cũng đồng dạng mất đi non nửa","trangThaiMoc":"Tổn thất gần một nửa"}]},"capNhatToi":"@c1483","nguon":["@c1483"]},{"id":"dai-quan-trung-hai","name":"Đại quân Trùng hải","cn":"","type":"quan-doi","typeLabel":"Lực lượng chiến tranh","diaBan":"Phù Du tộc","nhanVatChinh":[],"blurb":"Lực lượng chiến tranh của Phù Du tộc có sức uy hiếp khiến cả chân linh cũng phải tránh lui.","detail":"Đại quân Trùng hải chỉ có khả năng được điều động khi Phù Du tộc đối diện nguy cơ ảnh hưởng tới sự sống còn. Mỗi lần xuất quân khiến bản tộc tổn hao quá nửa nguyên khí, vì vậy nhóm Mộc Thanh cho rằng lực lượng này khó được dùng chỉ để đối phó họ.","quyMo":"Có thể khiến chân linh phải tránh lui một phần.","trangThai":"Chưa xuất quân","quanHe":"Trực thuộc Phù Du tộc.","tabs":{"tienTrinh":[{"chuong":"@c1485","loai":"nhắc tới","importance":"bridge","giaiDoan":"Nguy cơ được hé lộ","text":"Sức mạnh và cái giá điều động đại quân Trùng hải được nhắc đến khi nhóm đánh giá khả năng Phù Du tộc truy kích.","anchor":"Phù Du tộc xuất động trùng hải cố nhiên ngay cả chân linh cũng phải tránh lui một phần"}]},"capNhatToi":"@c1485","nguon":["@c1485"]},{"id":"nhom-yeu-vuong-dia-uyen","name":"Nhóm yêu vương Địa Uyên","cn":"","type":"lien-minh","typeLabel":"Nhóm yêu vương","diaBan":"Địa Uyên","nhanVatChinh":["Mộc Thanh","Địa Huyết","Mỹ phụ đầu bạc","Lục Túc"],"blurb":"Nhóm yêu vương Địa Uyên phối hợp tiến vào khu vực Minh Hà thần nhũ.","detail":"Mộc Thanh, Địa Huyết và mỹ phụ đầu bạc hợp lực đối phó hai Minh Lôi Thú, trong khi Lục Túc được cho là đang chặt đứt mối liên hệ giữa thần dịch và linh mạch.","thanhVien":[{"ten":"Mộc Thanh","chucVu":"Yêu vương","tuChuong":"@c1496","trangThai":"đang tham chiến"},{"ten":"Địa Huyết","chucVu":"Yêu vương","tuChuong":"@c1496","trangThai":"đang tham chiến"},{"ten":"Mỹ phụ đầu bạc","chucVu":"Yêu vương","tuChuong":"@c1496","trangThai":"đang tham chiến"},{"ten":"Lục Túc","chucVu":"Yêu vương","tuChuong":"@c1496","trangThai":"đang chặt đứt linh mạch"}],"trangThai":"Đang mưu lấy Minh Hà thần nhũ","capNhatToi":"@c1496","nguon":["@c1496"]},{"id":"dia-uyen-quy-vat","name":"Phe kim giáp khôi lỗi","cn":"","type":"khac","typeLabel":"Lực lượng trấn giữ thủy trì","diaBan":"Đại điện chứa thủy trì","nhanVatChinh":["Kim giáp khôi lỗi","Quỷ vật mình người mặt ngựa"],"blurb":"Lực lượng do kim giáp khôi lỗi chỉ huy để bảo vệ thủy trì và mối liên hệ với linh mạch.","detail":"Phe này phát động công kích nhóm ngoại lai và điều quỷ vật mình người mặt ngựa chặn đánh âm giáp quỷ binh.","tonChi":"Bảo vệ thủy trì và mối liên hệ với linh mạch.","lanhDaoHienThoi":"Kim giáp khôi lỗi","thanhVien":[{"ten":"Kim giáp khôi lỗi","chucVu":"Người chỉ huy","tuChuong":"@c1499","trangThai":"Đang hoạt động"},{"ten":"Quỷ vật mình người mặt ngựa","chucVu":"Thuộc hạ","tuChuong":"@c1499","trangThai":"Đang hoạt động"}],"trangThai":"Giao chiến","tabs":{"tienTrinh":[{"chuong":"@c1499","loai":"khai chiến","importance":"normal","giaiDoan":"Tấn công nhóm ngoại lai","trangThaiMoc":"Giao chiến","text":"Kim giáp khôi lỗi phát động tập kích và điều thuộc hạ chặn âm giáp quỷ binh để bảo vệ liên hệ giữa thủy trì với linh mạch.","anchor":"Nếu quả thực bị đối phương chặt đứt mối liên hệ giữa thủy trì và linh mạch thì cho dù hắn có tiêu diệt được mấy tên ngoại lai này nhưng khi trở về trong tộc vẫn hoài trọng tội."}]},"capNhatToi":"@c1499","nguon":["@c1499"]},{"id":"nhom-moc-thanh","name":"Nhóm Mộc Thanh – mỹ phụ đầu bạc – huyết bào nhân – Lục Túc","cn":"","type":"lien-minh","typeLabel":"Liên minh tạm thời","diaBan":"Đại điện chứa thủy trì","nhanVatChinh":["Mộc Thanh","Mỹ phụ đầu bạc","Huyết bào nhân","Lục Túc"],"blurb":"Liên minh tạm thời của các cường giả ngoại lai gồm Mộc Thanh, mỹ phụ đầu bạc, huyết bào nhân và Lục Túc, cùng tiến vào khu vực thủy trì. Sau khi Mộc Thanh bị Ngũ Long Trát giết chết, lực lượng này chịu tổn thất lớn và những thành viên còn lại bị ép vào khổ chiến.","detail":"Nhóm được hình thành như một liên minh tạm thời giữa các cường giả ngoại lai tiến vào khu vực thủy trì. Trong giao chiến, Mộc Thanh tử vong dưới Ngũ Long Trát, khiến lục sắc quang mạc thiếu pháp lực duy trì; mỹ phụ đầu bạc và huyết bào nhân tiếp tục khổ chiến trong lúc chờ Lục Túc thoát khỏi kim sắc quang trận. @c1499","thanhVien":[{"ten":"Mộc Thanh","chucVu":"Thành viên","tuChuong":"@c1499","trangThai":"Tử vong"},{"ten":"Mỹ phụ đầu bạc","chucVu":"Thành viên","tuChuong":"@c1499","trangThai":"Đang hoạt động"},{"ten":"Huyết bào nhân","chucVu":"Thành viên","tuChuong":"@c1499","trangThai":"Đang hoạt động"},{"ten":"Lục Túc","chucVu":"Thành viên","tuChuong":"@c1499","trangThai":"Đang ở trong quang trận"}],"trangThai":"Suy yếu","tabs":{"tienTrinh":[{"chuong":"@c1499","loai":"suy","importance":"major","giaiDoan":"Mất Mộc Thanh","trangThaiMoc":"Suy yếu","text":"Liên minh mất Mộc Thanh, lục sắc quang mạc thiếu pháp lực duy trì và các thành viên còn lại bị ép vào khổ chiến.","anchor":"Mỹ phụ đầu bạc vốn vì cái chết của Mộc Thanh mà thâm tâm e ngại Ngũ Long Trát"}]},"capNhatToi":"@c1499","nguon":["@c1499"],"dacDiem":"Liên minh tạm thời của các cường giả ngoại lai; sức chiến đấu và thế trận bị ảnh hưởng rõ rệt khi mất một thành viên chủ chốt.","congNang":["Duy trì lục sắc quang mạc bằng pháp lực; sau khi Mộc Thanh tử vong, quang mạc bị thiếu pháp lực duy trì. @c1499"]},{"id":"truong-nguyen-toc","name":"Trường Nguyên Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Không rõ","nhanVatChinh":["Lão giả họ Khương"],"blurb":"Chủng tộc cực kỳ thưa thớt, có nhiều thiên phú tu luyện đặc biệt.","detail":"Người trong Trường Nguyên Tộc trời sinh tinh thông nhiều loại thần thông và công pháp. Thân thể hiện tại của lão giả họ Khương vốn thuộc một thành viên của tộc này trước khi bị đoạt xá và luyện hóa.","nguonGoc":"Không rõ","quyMo":"Vô cùng thưa thớt","caoThuManhNhat":"Không rõ","soCaoThu":"Không rõ","thanhVien":[{"ten":"Lão giả họ Khương","chucVu":"Tu sĩ Đại Thừa","tuChuong":"@c1512","trangThai":"đang-gắn-bó"}],"tabs":{"tienTrinh":[{"chuong":"@c1512","loai":"nhắc tới","importance":"normal","giaiDoan":"Đặc điểm chủng tộc được hé lộ","text":"Lão giả họ Khương cho biết Trường Nguyên Tộc rất thưa thớt và thành viên trời sinh có nhiều thiên phú tu luyện đặc biệt.","anchor":"Người trong tộc này trời sinh đã tinh thông các loại thần thông công pháp, trong cơ thể ẩn chứa các loại thiên phú tu luyện khó có thể ngờ được."},{"chuong":"@c1515","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ truyền thừa","text":"Lão giả họ Khương cho biết mình chuyển sang tu thần thông của Trường Nguyên Tộc sau khi dung hợp tinh hồn và thân thể với tộc.","anchor":"Sau đó bởi vì dung hợp tinh hồn và thân thể với Trường Nguyên Tộc ta mới chuyển tu thần thông của Trường Nguyên Tộc.","trangThaiMoc":"Đang tồn tại"}]},"capNhatToi":"@c1512","nguon":["@c1512","@c1515"]},{"id":"giac-xi-toc","name":"Giác Xi Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Ngoài biển, cách lãnh địa Phi Linh Tộc một đại dương","nhanVatChinh":["Mẫn đạo hữu","Đại Tế Ti của Giác Xi Tộc","Lão giả họ Đồ","Nanh đạo hữu","Hai thái thượng trưởng lão Giác Xi tộc"],"blurb":"Giác Xi Tộc là một đại tộc từng liên thủ với Hải Vương Tộc, tiêu hao lượng lớn linh thạch để đưa đại diện vượt đại dương truy tìm Huyền Thiên Trảm Linh Kiếm. Trong quá trình mở rộng chiến sự, tộc này chiếm hơn phân nửa thành thị trong khu vực, tổ chức phong tỏa truy tìm và liên tiếp công phá nhiều thành trì. (+) Thế lực từng phá giới tới Phong Nguyên đại lục để tìm Huyền Thiên chi bảo mới. [CAN-SOAT-GOP]","detail":"Giác Xi Tộc có Đại Tế Ti nắm giữ bí thuật dự đoán vị trí bảo vật và từng cử Mẫn đạo hữu làm đại diện truy tìm Huyền Thiên Trảm Linh Kiếm. Tộc này cùng Hải Vương Tộc coi việc ngăn thanh kiếm rơi vào tay thế lực khác là đại sự có thể dẫn đến chiến tranh diệt tộc, vì vậy đã bỏ ra lượng lớn linh thạch để truyền tống người vượt đại dương đến khu vực Phi Linh Tộc. Về sau, truy binh Giác Xi Tộc áp sát khu vực giao tranh; thế lực này còn chiếm hơn phân nửa thành thị trong khu vực và huy động mạng lưới đó để phong tỏa đường, truy tìm mục tiêu. Khi chiến sự mở rộng, Giác Xi Tộc phát động tấn công và lợi dụng lúc lực lượng chủ lực đối phương bị vây để liên tiếp phá mười ba thành.","quyMo":"Đại tộc có thực lực vượt xa Phi Linh Tộc theo lời hai đại diện","quanHe":"Liên thủ với Hải Vương Tộc truy tìm Huyền Thiên Trảm Linh Kiếm","trangThai":"Đang tiến công Vân Thành","thanhVien":[{"ten":"Mẫn đạo hữu","chucVu":"Đại diện","tuChuong":"@c1527","trangThai":"Đang thi hành nhiệm vụ"},{"ten":"Đại Tế Ti của Giác Xi Tộc","chucVu":"Đại Tế Ti","tuChuong":"@c1527","trangThai":"Không rõ"},{"ten":"Lão giả họ Đồ","chucVu":"Cường giả Hợp Thể kỳ","tuChuong":"@c1569","trangThai":"đang hoạt động"},{"ten":"Nanh đạo hữu","chucVu":"Cường giả Hợp Thể kỳ","tuChuong":"@c1569","trangThai":"đang hoạt động"},{"ten":"Hai thái thượng trưởng lão Giác Xi tộc","chucVu":"Thái thượng trưởng lão","tuChuong":"@c1741","trangThai":"Đang đi theo đại quân"}],"tabs":{"tienTrinh":[{"chuong":"@c1527","loai":"liên minh","importance":"normal","giaiDoan":"Vượt biển truy tìm bảo vật","trangThaiMoc":"Liên thủ với Hải Vương Tộc","text":"Giác Xi Tộc cùng Hải Vương Tộc tiêu hao lượng lớn linh thạch để truyền tống đại diện vượt đại dương truy tìm Huyền Thiên Trảm Linh Kiếm.","anchor":"hai tộc chúng ta lần này liên thủ tiêu phí linh thạch cực lớn mới đưa chúng ta truyền tống vượt đại dương tới đây"},{"chuong":"@c1560","loai":"nhắc tới","importance":"normal","giaiDoan":"Truy binh áp sát","text":"Truy binh Giác Xi tộc áp sát khu vực giao tranh và bị Hoằng Diệt lợi dụng làm sức ép đối với Hàn Lập.","anchor":"khắp nơi đều là truy binh của Giác Xi tộc"},{"chuong":"@c1569","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Phong tỏa khu vực","trangThaiMoc":"Kiểm soát hơn phân nửa thành thị","text":"Giác Xi tộc đã chiếm hơn phân nửa thành thị trong khu vực và huy động mạng lưới này để phong tỏa đường, truy tìm Hàn Lập.","anchor":"thành thị khu vực này hơn phân nửa đã rơi vào tay bổn tộc"},{"chuong":"@c1601","loai":"khai chiến","importance":"normal","giaiDoan":"Tấn công khu vực Vân thành","text":"Giác Xi Tộc gần đây phát động tấn công.","anchor":"do Giác Xi Tộc gần đây tấn công"},{"chuong":"@c1664","loai":"nhac-toi","importance":"normal","giaiDoan":"Bị truy tìm tại Vân Thành","text":"Có gián điệp xâm nhập cung phụng đường. Liên minh thánh tộc họp truy tìm nửa năm không thấy tung tích.","anchor":"tên Giác Xi tộc xông vào cung phụng đường kia, một chút tung tích cũng không thấy"},{"chuong":"@c1741","loai":"khai chiến","importance":"normal","giaiDoan":"Tiến công Vân Thành","text":"Giác Xi tộc lợi dụng lúc lực lượng chủ lực đối phương bị vây để liên tiếp phá mười ba thành rồi tiến đánh Vân Thành.","anchor":"Còn đại quân Giác Xi tộc lợi dụng cơ hội liên tiếp công phá mười ba thành rồi tiến công đánh Vân Thành"}]},"capNhatToi":"@c1527","nguon":["@c1527","@c1560","@c1566","@c1569","@c1601","@c1664","@c1741","@c1864"],"uyLuc":"Giác Xi Tộc từng chiếm hơn phân nửa thành thị trong khu vực và, trong một đợt tiến công, liên tiếp phá mười ba thành. @c1569 @c1741","dacDiem":"Đại tộc có năng lực viễn trình truy tìm bảo vật, tổ chức phong tỏa trên địa bàn rộng và tiến hành chiến tranh mở rộng lãnh thổ.","congNang":["Đại Tế Ti có bí thuật dự đoán vị trí bảo vật.","Có thể tiêu hao lượng lớn linh thạch để truyền tống đại diện vượt đại dương truy tìm mục tiêu. @c1527","Huy động mạng lưới thành thị đã chiếm giữ để phong tỏa đường và tổ chức truy tìm. @c1569","Tổ chức lực lượng truy binh áp sát khu vực giao tranh. @c1560","Phát động chiến tranh, lợi dụng lúc chủ lực đối phương bị vây để liên tiếp công phá thành trì. @c1601 @c1741"]},{"id":"hai-vuong-toc","name":"Hải Vương Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Ngoài biển, cách lãnh địa Phi Linh Tộc một đại dương","nhanVatChinh":["Giản huynh"],"blurb":"Đại tộc liên thủ với Giác Xi Tộc để truy tìm Huyền Thiên Trảm Linh Kiếm. Hải Vương Tộc cử Giản huynh vượt biển đến lãnh địa Phi Linh Tộc thực hiện nhiệm vụ.","detail":"Theo lời Giản huynh, chỉ một phần mười thực lực của Hải Vương Tộc và Giác Xi Tộc cũng đủ tiêu diệt Phi Linh Tộc. Tuy vậy, hai tộc chưa lập tức phát động viễn chinh vì lo các đại tộc khác lợi dụng lúc hậu phương trống trải.","quyMo":"Đại tộc có thực lực vượt xa Phi Linh Tộc theo lời Giản huynh","quanHe":"Liên thủ với Giác Xi Tộc truy tìm Huyền Thiên Trảm Linh Kiếm","trangThai":"Đang phái người hoạt động tại lãnh địa Phi Linh Tộc","thanhVien":[{"ten":"Giản huynh","chucVu":"Đại diện","tuChuong":"@c1527","trangThai":"Đang thi hành nhiệm vụ"}],"tabs":{"tienTrinh":[{"chuong":"@c1527","loai":"liên minh","importance":"normal","giaiDoan":"Vượt biển truy tìm bảo vật","trangThaiMoc":"Liên thủ với Giác Xi Tộc","text":"Hải Vương Tộc cùng Giác Xi Tộc đưa đại diện vượt biển đến khu vực Phi Linh Tộc để tìm Huyền Thiên Trảm Linh Kiếm.","anchor":"Giác Xi Tộc các ngươi cùng Hải Vương Tộc chúng ta, chỉ cần xuất ra một phần mười thực lực cũng dễ dàng tiêu diệt tộc loại như Phi Linh Tộc này"}]},"capNhatToi":"@c1527","nguon":["@c1527"]},{"id":"giac-dong-toc","name":"Giác Đổng Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Chưa rõ","nhanVatChinh":["Duyệt đạo hữu"],"blurb":"Chủng tộc của Duyệt đạo hữu, một trong hai người trực tiếp chủ trì pháp trận huyết tế.","detail":"Đại diện Giác Đổng Tộc tham gia tìm kiếm Huyền Thiên Trảm Linh Kiếm và đề nghị tiến hành lần triệu hồi thứ hai sau khi lần đầu thất bại.","quanHe":"Phối hợp với Hải Vương Tộc và các cao tầng Phi Linh Tộc trong cuộc huyết tế.","trangThai":"Đang tham gia triệu hồi Huyền Thiên Trảm Linh Kiếm","thanhVien":[{"ten":"Duyệt đạo hữu","chucVu":"Đại diện tham gia huyết tế","tuChuong":"@c1534","trangThai":"Đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1534","loai":"liên minh","importance":"normal","giaiDoan":"Triệu hồi lần hai","text":"Duyệt đạo hữu đại diện Giác Đổng Tộc đề nghị tái khởi huyết tế để tiếp tục tìm Huyền Thiên Trảm Linh Kiếm.","anchor":"là độc giác thanh niên của Giác Đổng Tộc.","trangThaiMoc":"Tiếp tục tham gia huyết tế"}]},"capNhatToi":"@c1534","nguon":["@c1534","@c1578"]},{"id":"hoa-duong-toc","name":"Hỏa Dương Tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Hải đảo có Hỏa Dương Thành","nhanVatChinh":["Viêm Vũ","Đại tế ti Hỏa Dương Tộc"],"blurb":"Chủng tộc có một phân nhánh nhỏ sinh sống trên hải đảo, lấy Hỏa Dương Thành làm điểm cư trú trung tâm.","detail":"Phân nhánh trên đảo có người phụ trách hỗ trợ cúng tế, đội săn xà nhân và một đại tế ti đủ tư cách tiếp đãi người ngoài được xem là thượng tộc.","quyMo":"Một phân nhánh nhỏ trên đảo","lanhDaoHienThoi":"Đại tế ti Hỏa Dương Tộc","thanhVien":[{"ten":"Viêm Vũ","chucVu":"Phụ trách hỗ trợ cúng tế","tuChuong":"@c1536","trangThai":"Đang hoạt động"},{"ten":"Đại tế ti Hỏa Dương Tộc","chucVu":"Đại tế ti","tuChuong":"@c1536","trangThai":"Đang giữ chức"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1536","tabs":{"tienTrinh":[{"chuong":"@c1536","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ diện phân nhánh trên đảo","text":"Viêm Vũ cho biết cộng đồng trên đảo chỉ là một phân nhánh nhỏ của Hỏa Dương Tộc và chuẩn bị đưa Hàn Lập tới gặp đại tế ti.","anchor":"Đây chỉ là một phân nhánh nho nhỏ của Hỏa Dương Tộc","trangThaiMoc":"Đang hoạt động"}]},"nguon":["@c1536"]},{"id":"hai-toc-lang-gieng-cua-hoa-duong-toc","name":"Hai tộc láng giềng của Hỏa Dương Tộc","cn":"","aliases":[],"type":"bo-toc","typeLabel":"Hai bộ tộc chưa rõ tên","diaBan":"Hải vực gần Hỏa Vân đảo","nhanVatChinh":[],"blurb":"Hai bộ tộc láng giềng từng hỗ trợ lẫn nhau với Hỏa Dương Tộc nhưng sau đó đều bị tiêu diệt. Nữ nhân trong tộc bị ăn sống, còn toàn bộ nam nhân mất tích, khiến Hỏa Dương Tộc lo sợ sẽ trở thành mục tiêu kế tiếp.","detail":"Hai tộc sinh sống gần Hỏa Dương Tộc và từng có quan hệ hỗ trợ lẫn nhau với bộ tộc này. Đến biến cố diệt tộc, nữ nhân của cả hai tộc bị ăn sống, chỉ còn lại xương trắng, trong khi toàn bộ nam nhân đều mất tích; kết cục của họ trở thành nguyên nhân khiến Hỏa Dương Tộc lo ngại tai họa tương tự sẽ giáng xuống mình. @c1538","quanHe":"Từng hỗ trợ lẫn nhau với Hỏa Dương Tộc.","trangThai":"đã bị tiêu diệt","tabs":{"tienTrinh":[{"chuong":"@c1538","loai":"diệt/sáp nhập","importance":"major","giaiDoan":"Bị diệt tộc","text":"Hai tộc láng giềng từng hỗ trợ Hỏa Dương Tộc đã bị tiêu diệt; nữ nhân bị ăn sống còn nam nhân mất tích.","anchor":"Nửa năm trước, một phân chi gần chúng ta đã bị diệt tộc hoàn toàn, tất cả nữ nhân trong tộc đều bị người ta ăn sống","trangThaiMoc":"đã bị tiêu diệt"}]},"capNhatToi":"@c1538","nguon":["@c1538"],"dacDiem":"Hai bộ tộc láng giềng có quan hệ tương trợ với Hỏa Dương Tộc; cả hai cùng chịu kết cục nữ nhân bị ăn sống và nam nhân mất tích. @c1538"},{"id":"oa-thi-toc","name":"Oa Thị Tộc","cn":"","type":"bo-toc","typeLabel":"Bộ tộc","diaBan":"Từng giao chiến tại Lôi Minh đại lục","nhanVatChinh":["Đại tế tự Hỏa Dương tộc","Bạch Châu nhi"],"blurb":"Bộ tộc từng là tử địch của Ô La Tộc và đã giao chiến với đối phương tại Lôi Minh đại lục. Người trong tộc từng tin rằng Ô La Tộc đã bị tiêu diệt hoàn toàn từ rất nhiều ngàn năm trước.","detail":"Nữ tử Oa Thị Tộc là mục tiêu bị Ô La Tộc thôn phệ huyết nhục. Đại tế tự nghi một số dư nghiệt của kẻ thù đã trốn ra hải ngoại và âm thầm tồn tại cho tới hiện tại.","quanHe":"Tử địch cổ xưa của Ô La Tộc.","trangThai":"Còn tồn tại","capNhatToi":"@c1539","tabs":{"tienTrinh":[{"chuong":"@c1539","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ lịch sử đối địch","trangThaiMoc":"Còn tồn tại","text":"Lịch sử Oa Thị Tộc từng đại chiến với Ô La Tộc tại Lôi Minh đại lục được đại tế tự thuật lại.","anchor":"Ô La Tộc cùng Oa Thị Tộc chúng ta đánh nhau một trận tại Lôi Minh đại lục"}]},"nguon":["@c1539"]},{"id":"o-la-toc","name":"Ô La Tộc","cn":"","type":"bo-toc","typeLabel":"Bộ tộc","diaBan":"Bị nghi ẩn náu ngoài hải vực Lôi Minh đại lục","nhanVatChinh":[],"blurb":"Tử địch cổ xưa của Oa Thị Tộc, từng bị cho là đã bị tiêu diệt hoàn toàn sau một trận chiến tại Lôi Minh đại lục. Đại tế tự Hỏa Dương Tộc nghi dư nghiệt của tộc này đã sống sót ngoài hải vực và tiêu diệt hai bộ tộc láng giềng.","detail":"Ô La Tộc có khả năng thôn phệ huyết nhục nữ tử Oa Thị Tộc. Việc tộc này còn tồn tại và đứng sau đại nạn hiện tại mới là phỏng đoán, chưa có chứng cứ trực tiếp.","nguonGoc":"Từng hoạt động tại Lôi Minh đại lục trước khi bị Oa Thị Tộc tuyên bố tiêu diệt.","quanHe":"Tử địch cổ xưa của Oa Thị Tộc.","trangThai":"Nghi còn dư nghiệt","capNhatToi":"@c1539","tabs":{"tienTrinh":[{"chuong":"@c1539","loai":"nhắc tới","importance":"normal","giaiDoan":"Bị nghi tái xuất","trangThaiMoc":"Nghi còn dư nghiệt","text":"Đại tế tự nghi Ô La Tộc đã sống sót ngoài hải vực và là thủ phạm tiêu diệt hai bộ tộc, nhưng chưa có chứng cứ xác nhận.","anchor":"Hơn nữa ngoại trừ Ô La Tộc thì còn có bộ tộc nào có thể thôn phệ huyết nhục nữ tử của chúng ta."}]},"nguon":["@c1539"]},{"id":"o-la-vuong-toc","name":"Ô La Vương Tộc","cn":"","type":"vuong-toc","typeLabel":"Huyết mạch vương tộc","diaBan":"Không rõ","nhanVatChinh":[],"blurb":"Huyết mạch vương tộc của Ô La Tộc từng bị cho là đã tuyệt diệt nhưng nay bị nghi vẫn còn người sống sót.","detail":"Ô La Vương Tộc trời sinh khắc chế Oa Thị bộ tộc, khiến các nhánh không thuộc hoàng tộc khó phát huy nổi một thành thần thông. Đại tế tự Hỏa Dương tộc nghi một thành viên vương tộc đã tu luyện đại thành và tham gia các cuộc tập kích gần đây.","dacDiem":"Trời sinh khắc chế các nhánh không thuộc hoàng tộc của Oa Thị bộ tộc.","trangThai":"Bị nghi đã tái xuất","tabs":{"tienTrinh":[{"chuong":"@c1540","loai":"nhắc tới","importance":"normal","giaiDoan":"Nghi tái xuất","text":"Dấu vết trong các cuộc tập kích khiến Đại tế tự nghi huyết mạch Ô La Vương Tộc chưa tuyệt diệt và đã có người tu luyện đại thành.","anchor":"vương tộc này trời sinh có khả năng khắc chế Oa Thị bộ tộc chúng ta"}]},"capNhatToi":"@c1540","nguon":["@c1540"]},{"id":"han-tinh-toc","name":"Hàn Tinh tộc","cn":"","type":"toc-nguoi","typeLabel":"Tộc người","diaBan":"Hỏa Hô quần đảo","nhanVatChinh":["Nữ tử cầm đầu nhóm Hàn Tinh tộc"],"blurb":"Tộc người không thể hấp thu thiên địa linh khí nhưng có trí tuệ cao, thiên phú phun hàn khí và năng lực bồi dục linh dược nổi bật.","detail":"Hàn Tinh tộc không sinh ra tu luyện giả nên thường phải nương tựa các tộc hoặc tu sĩ mạnh để được bảo hộ. Thành viên của tộc giữ dung mạo trẻ trung cho tới khi gần hết thọ nguyên, đồng thời giỏi chăm sóc động phủ, quản lý dược viên và bồi dục linh dược hơn tu luyện giả thông thường. Tại Hỏa Hô quần đảo có hơn vạn người thuộc tộc này.","nguonGoc":"Không rõ","tonChi":"Nương tựa cường giả để được bảo hộ và dùng sở trường quản lý động phủ, dược viên.","lanhDaoHienThoi":"Không rõ","capBac":"Không rõ","quyMo":"Hơn vạn người tại Hỏa Hô quần đảo","caoThuManhNhat":"Không có tu luyện giả được xác nhận","soCaoThu":"Không có tu luyện giả","tranPhai":"Không rõ","quanHe":"Một nhóm từng phục vụ Ngân Sa cư sĩ đã chuyển sang nương tựa thiếu phụ váy đen.","trangThai":"Tồn tại","thanhVien":[{"ten":"Nữ tử cầm đầu nhóm Hàn Tinh tộc","chucVu":"Người đứng đầu nhóm người hầu","tuChuong":"@c1553","trangThai":"Đang nương tựa thiếu phụ váy đen"}],"capNhatToi":"@c1553","tabs":{"tienTrinh":[{"chuong":"@c1553","loai":"nhắc tới","importance":"normal","giaiDoan":"Nhóm người hầu đổi nơi nương tựa","text":"Sau khi Ngân Sa cư sĩ chết, nhóm Hàn Tinh tộc tại băng điện chuyển sang đi theo thiếu phụ váy đen.","anchor":"Cả Hoa Hô quần đảo cũng bất quá có hơn vạn người","trangThaiMoc":"Một nhóm thành viên đổi người bảo hộ"}]},"nguon":["@c1553"]},{"id":"thien-van-muoi-ba-toc","name":"Thiên Vân mười ba tộc","cn":"","type":"lien-minh","typeLabel":"Liên minh chủng tộc","diaBan":"Khu vực Thiên Vân, gồm Lục Quang Thành","nhanVatChinh":["Nguyên huynh","Dị tộc nhân da màu lục nhạt","Hoằng huynh","Thiên Vân","Giáp Thiên Mộc"],"blurb":"Thiên Vân mười ba tộc là liên hợp gồm mười ba tộc tại khu vực Thiên Vân, quản lý nhiều thành trì và sở hữu lực lượng quân sự tập trung tại Kim Giáp thành. Khi bị Giác Xi Tộc tiến công và thâu tóm, thế lực này đứng trước nguy cơ mất các cứ điểm trọng yếu, trong đó Lục Quang Thành bị quân tiên phong áp sát còn Vân Thành có thể trở thành trung tâm chiến sự.","detail":"Thiên Vân mười ba tộc là cộng đồng các tộc quản lý khu vực Thiên Vân, bao gồm những thành trì như Lục Quang Thành, Kim Giáp thành và Vân Thành. Trong cuộc tiến công của Giác Xi Tộc, hàng vạn người chạy nạn tập trung tại Lục Quang Thành giữa lúc các tuyến Truyền Tống trận mất hiệu lực, còn quân tiên phong đối phương áp sát nhằm ngăn người trong thành rút lui. Kim Giáp thành là nơi tập trung nhiều quân đội tinh nhuệ của liên hợp, trong khi Vân Thành được xác định là thành lớn thứ ba và có khả năng trở thành trung tâm chiến sự.","quyMo":"Liên hợp mười ba tộc","quanHe":"Đang bị Giác Xi Tộc tiến công và thâu tóm.","trangThai":"Tập trung lực lượng tại Kim Giáp thành","capNhatToi":"@c1556","thanhVien":[{"ten":"Nguyên huynh","chucVu":"Tu sĩ Luyện Hư trấn giữ Lục Quang Thành","tuChuong":"@c1556","trangThai":"Đang hoạt động"},{"ten":"Dị tộc nhân da màu lục nhạt","chucVu":"Tu sĩ Luyện Hư trấn giữ Lục Quang Thành","tuChuong":"@c1556","trangThai":"Đang hoạt động"},{"ten":"Hoằng huynh","chucVu":"Tu sĩ Luyện Hư trấn giữ Lục Quang Thành","tuChuong":"@c1556","trangThai":"Đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1556","loai":"suy","importance":"major","giaiDoan":"Bị Giác Xi Tộc thâu tóm","text":"Thiên Vân mười ba tộc bị Giác Xi Tộc tiến công và thâu tóm, khiến Lục Quang Thành bị quân tiên phong áp sát.","anchor":"Giác Xi Tộc bắt đầu thâu tóm Thiên Vân mười ba tộc chúng ta","trangThaiMoc":"Suy yếu trong chiến sự"},{"chuong":"@c1569","loai":"nhắc tới","importance":"normal","giaiDoan":"Tập trung tại Kim Giáp thành","trangThaiMoc":"Quân đội tinh nhuệ và cường giả tập trung","text":"Kim Giáp thành được xác nhận là nơi tập trung nhiều quân đội tinh nhuệ của Thiên Vân mười ba tộc.","anchor":"cho nên là nơi tập trung nhiều quân đội tinh nhuệ của mười ba tộc"},{"chuong":"@c1575","loai":"nhắc tới","importance":"normal","giaiDoan":"Đối mặt nguy cơ đại chiến","text":"Vân Thành được xác định là thành lớn thứ ba của Thiên Vân mười ba tộc và có thể trở thành trung tâm chiến sự.","anchor":"thành lớn thứ ba ở Thiên Vân mười ba tộc"}]},"nguon":["@c1556","@c1569","@c1575"],"uyLuc":"Lực lượng quân sự nổi bật nhất đã được xác nhận là nhiều quân đội tinh nhuệ tập trung tại Kim Giáp thành. @c1569","dacDiem":"Liên hợp gồm mười ba tộc tại khu vực Thiên Vân, có hệ thống thành trì với Kim Giáp thành là nơi tập trung quân tinh nhuệ và Vân Thành là thành lớn thứ ba.","congNang":["Quản lý khu vực Thiên Vân cùng nhiều thành trì thuộc cộng đồng mười ba tộc.","Tập trung nhiều quân đội tinh nhuệ tại Kim Giáp thành. @c1569"]},{"id":"van-co-toc","name":"Vạn Cổ Tộc","cn":"","type":"bo-toc","typeLabel":"Bộ tộc","diaBan":"Có nhiều đại trưởng lão dự kiến tọa trấn tại Vân thành","nhanVatChinh":["Gã đầu to","Giáp Thiên Mộc"],"blurb":"Một thành viên của Thiên Vân mười ba tộc, nổi bật với khôi lỗi cấp thông linh và các bảo vật quý hiếm.","detail":"Vạn Cổ Tộc coi vật trong ba hộp ngọc đặc biệt quan trọng và sẵn sàng dùng khôi lỗi cấp thông linh, bảo vật đồng cấp hoặc Vạn Diệu đan để trao đổi. Nhiều đại trưởng lão của tộc dự kiến tập trung tại Vân thành để ứng phó Giác Xi Tộc.","nguonGoc":"Không rõ","lanhDaoHienThoi":"Các đại trưởng lão chưa rõ danh tính","caoThuManhNhat":"Đại trưởng lão chưa rõ cảnh giới","quanHe":"Thành viên Thiên Vân mười ba tộc; đối đầu Giác Xi Tộc","trangThai":"Tập trung lực lượng tại Vân thành","thanhVien":[{"ten":"Gã đầu to","chucVu":"Thành viên tại Lục Quang Thành","tuChuong":"@c1559","trangThai":"Đang hoạt động"},{"ten":"Giáp Thiên Mộc","chucVu":"","tuChuong":"@c1571","trangThai":"dang-thuoc"}],"capNhatToi":"@c1559","tabs":{"tienTrinh":[{"chuong":"@c1559","loai":"liên minh","importance":"normal","giaiDoan":"Tọa trấn Vân thành","text":"Nhiều đại trưởng lão Vạn Cổ Tộc dự kiến tọa trấn tại Vân thành cùng các trưởng lão Thiên Vân mười ba tộc.","anchor":"trong đó cũng có mấy đại trưởng lão trong Vạn Cổ tộc chúng ta đích thân tọa trấn trong thành"}]},"nguon":["@c1559","@c1571"]},{"id":"mac-luc-toc","name":"Mặc Lục tộc","cn":"","type":"bo-toc","typeLabel":"Bộ tộc","diaBan":"Không rõ","nhanVatChinh":["Dị tộc nhân da màu lục nhạt","Chưởng quỹ Mặc Lục Tộc","Nữ tử Mặc Lục Tộc"],"blurb":"Một bộ tộc thuộc Thiên Vân mười ba tộc, sở hữu bí thuật ẩn nặc đặc biệt.","detail":"Bí thuật đặc thù của Mặc Lục tộc có thể khiến người thi triển gần như biến mất khỏi cảm giác thông thường. Muốn phát hiện người đang ẩn nặc cần tu vi cao hơn hoặc có thần thông chuyên biệt.","nguonGoc":"Không rõ","tranPhai":"Bí thuật ẩn nặc của Mặc Lục tộc","quanHe":"Thành viên Thiên Vân mười ba tộc","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Dị tộc nhân da màu lục nhạt","chucVu":"Thành viên","tuChuong":"@c1559","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1559","tabs":{"tienTrinh":[{"chuong":"@c1559","loai":"nhắc tới","importance":"bridge","giaiDoan":"Hé lộ bí thuật đặc thù","text":"Mặc Lục tộc được xác nhận sở hữu một bí thuật ẩn nặc đặc biệt.","anchor":"đây là bí thuật ẩn nặc đặc biệt của Mặc Lục tộc"}]},"nguon":["@c1559","@c1577","@c1597"]},{"id":"hoa-nguyet-toc","name":"Hỏa Nguyệt tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"","nhanVatChinh":["Hoằng Diệt"],"blurb":"Một dị tộc được Hoằng Diệt xác nhận là bộ tộc của mình.","detail":"Hoằng Diệt dựa vào thân phận Hỏa Nguyệt tộc để chất vấn việc Hàn Lập không nhận ra lai lịch của hắn. Hàn Lập nghi ngờ hắn đã đầu nhập Giác Xi tộc.","thanhVien":[{"ten":"Hoằng Diệt","chucVu":"","tuChuong":"@c1560","trangThai":"thành viên"}],"capNhatToi":"@c1560","tabs":{"tienTrinh":[{"chuong":"@c1560","loai":"nhắc tới","importance":"bridge","giaiDoan":"Lộ thân phận","text":"Hoằng Diệt tự nhận mình là người của Hỏa Nguyệt tộc.","anchor":"Hỏa Nguyệt tộc chúng ta mà cũng không nhận ra sao"}]},"nguon":["@c1560"]},{"id":"thien-van-chu-toc","name":"Thiên Vân chư tộc","cn":"","type":"lien-minh","typeLabel":"Liên minh các tộc","diaBan":"Thiên Vân","nhanVatChinh":["Hoằng Diệt"],"blurb":"Liên minh các tộc từng bị Giác Xi Tộc cài Hoằng Diệt vào làm gian tế.","detail":"Hoằng Diệt được lão giả họ Đồ bố trí trà trộn vào Thiên Vân chư tộc. Sau biến cố tại Lục Quang Thành, người của liên minh trở thành mục tiêu truy quét của quân Giác Xi Tộc.","quanHe":"Bị Giác Xi Tộc cài gian tế và truy quét","trangThai":"Đang chịu cuộc truy sát của Giác Xi Tộc","thanhVien":[{"ten":"Hoằng Diệt","chucVu":"Gian tế trà trộn","tuChuong":"@c1562","trangThai":"đã tử vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1562","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ kế hoạch cài gian tế","text":"Việc Hoằng Diệt từng được bố trí trà trộn vào Thiên Vân chư tộc được tiết lộ.","anchor":"Lúc đầu trong lúc vô tình mang hắn về, bảo hắn trà trộn vào Thiên Vân chư tộc","trangThaiMoc":"Bị cài gian tế"}]},"capNhatToi":"@c1562","nguon":["@c1562"]},{"id":"viem-he-giac-xi-toc","name":"Viêm Hệ Giác Xi Tộc","cn":"","type":"chi-he","typeLabel":"Chi hệ","diaBan":"Không rõ","nhanVatChinh":["Lão giả họ Đồ","Hoằng Diệt"],"blurb":"Một chi hệ của Giác Xi Tộc, có các trưởng lão chuẩn bị việc tẩy tủy và chuyển hóa Hoằng Diệt.","detail":"Sau khi Hoằng Diệt hoàn thành nhiệm vụ nằm vùng, các trưởng lão Viêm Hệ vốn sẽ tẩy tủy để biến hắn hoàn toàn thành người Giác Xi Tộc. Kế hoạch không thể thực hiện vì hắn đã tử vong.","quanHe":"Chi hệ trực thuộc Giác Xi Tộc","trangThai":"Kế hoạch chuyển hóa Hoằng Diệt đã thất bại","thanhVien":[{"ten":"Lão giả họ Đồ","chucVu":"Chỉ huy","tuChuong":"@c1562","trangThai":"đang hoạt động"},{"ten":"Hoằng Diệt","chucVu":"Người dự kiến được chuyển hóa","tuChuong":"@c1562","trangThai":"đã tử vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1562","loai":"nhắc tới","importance":"normal","giaiDoan":"Kế hoạch tẩy tủy thất bại","text":"Các trưởng lão Viêm Hệ đã chuẩn bị tẩy tủy cho Hoằng Diệt, nhưng kế hoạch chấm dứt vì hắn tử vong.","anchor":"trưởng lão Viêm Hệ bộ tộc chúng ta cũng đã chuẩn bị tốt","trangThaiMoc":"Không thể chuyển hóa Hoằng Diệt"}]},"capNhatToi":"@c1562","nguon":["@c1562"]},{"id":"tam-mi-toc","name":"Tâm Mị Tộc","cn":"","type":"chung-toc","typeLabel":"Tộc quần","diaBan":"Lôi Minh đại lục","nhanVatChinh":["Dị tộc nhân Tâm Mị Tộc"],"blurb":"Một tộc nhỏ trên Lôi Minh đại lục, có thiên phú đặc biệt về cảm ứng nguy hiểm.","detail":"Thành viên Tâm Mị Tộc được biết có thần thông trời phú giúp cảm nhận nguy hiểm. Một tu sĩ Luyện Hư sơ kỳ của tộc đã che giấu tu vi để rời Lục Quang Thành nhưng sau đó bị Hóa Huyết Ly Hồn đại pháp sát hại.","nguonGoc":"Tộc quần trên Lôi Minh đại lục","quyMo":"Tộc nhỏ","trangThai":"Đang tồn tại","thanhVien":[{"ten":"Dị tộc nhân Tâm Mị Tộc","chucVu":"Tu sĩ Luyện Hư sơ kỳ","tuChuong":"@c1563","trangThai":"Đã tử vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1563","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ đặc điểm tộc","trangThaiMoc":"Đang tồn tại","text":"Tâm Mị Tộc được xác định là một tộc nhỏ trên Lôi Minh đại lục và có thiên phú cảm ứng nguy hiểm.","anchor":"Tộc Tâm Mị của bọn họ tuy trên Lôi Minh đại lục chỉ là một tộc nhỏ"}]},"capNhatToi":"@c1563","nguon":["@c1563"]},{"id":"giac-hoang-toc","name":"Giác Hoàng Tộc","cn":"","type":"gia-toc","typeLabel":"Tộc群","diaBan":"","nhanVatChinh":["Lão giả họ Đồ"],"blurb":"Giác Hoàng Tộc là thế lực của lão giả họ Đồ, một cao giai trong tộc.","detail":"Lão giả họ Đồ được xác định là cao giai Giác Hoàng Tộc và có tu vi Hợp Thể sơ kỳ.","thanhVien":[{"ten":"Lão giả họ Đồ","chucVu":"Cao giai","tuChuong":"@c1565","trangThai":"dang-hoat-dong"}],"nguon":["@c1565"]},{"id":"truong-lao-hoi-giac-xi-toc","name":"Trưởng lão hội Giác Xi tộc","cn":"","aliases":[],"type":"co-cau-lanh-dao","typeLabel":"Cơ cấu lãnh đạo","diaBan":"Địa bàn do Giác Xi tộc kiểm soát","nhanVatChinh":[],"blurb":"Cơ cấu lãnh đạo cấp cao của Giác Xi tộc, có quyền trực tiếp điều động chiến thuyền và lực lượng phục vụ nhiệm vụ quan trọng.","detail":"Trưởng lão hội trực tiếp ra lệnh điều hai chiến thuyền sang hỗ trợ việc truy tìm Hàn Lập theo yêu cầu của Đồ sử giả. Mệnh lệnh này làm chậm kế hoạch công chiếm toàn bộ khu vực của Ân Tôn giả.","capBac":"Cơ cấu lãnh đạo cấp cao","quanHe":"Trực thuộc Giác Xi tộc","trangThai":"Đang hoạt động","capNhatToi":"@c1570","tabs":{"tienTrinh":[{"chuong":"@c1570","loai":"nhắc tới","importance":"normal","giaiDoan":"Điều động chiến thuyền","text":"Trưởng lão hội trực tiếp điều hai chiến thuyền sang hỗ trợ nhiệm vụ truy tìm Hàn Lập.","anchor":"chuyện điều động chiến thuyền là do trưởng lão hội đích thân hạ lệnh","trangThaiMoc":"Đang điều phối chiến thuyền"}]},"nguon":["@c1570"]},{"id":"doi-luyen-hu-ky-tren-chien-thuyen","name":"Đội Luyện Hư kỳ trên chiến thuyền","cn":"","aliases":[],"type":"doi-quan","typeLabel":"Đội viện binh","diaBan":"Chiến trường quanh chiến thuyền","nhanVatChinh":["Xích Túc quái nhân","Lão ẩu","Tên lùn Giác Xi tộc","Cự hán mặc da thú"],"blurb":"Nhóm tu sĩ Luyện Hư được truyền tống từ chiến thuyền tới để xử lý Hàn Lập và thu hồi mục tiêu liên quan đến hai ngọc hạp.","detail":"Nhóm có bốn tu sĩ Luyện Hư trực tiếp giao chiến, đồng thời nhận hỏa lực hỗ trợ từ chiến thuyền. Cự hán mặc da thú và lão ẩu lần lượt bị Hàn Lập giết trong cuộc đụng độ.","quyMo":"Nhiều tu sĩ Luyện Hư cùng chiến thuyền hỗ trợ.","caoThuManhNhat":"Các thành viên Luyện Hư kỳ","soCaoThu":"Ít nhất bốn tu sĩ Luyện Hư trực tiếp xuất hiện.","trangThai":"Tổn thất hai thành viên","thanhVien":[{"ten":"Xích Túc quái nhân","chucVu":"Thành viên","tuChuong":"@c1573","trangThai":"còn sống"},{"ten":"Lão ẩu","chucVu":"Thành viên","tuChuong":"@c1573","trangThai":"tử vong"},{"ten":"Tên lùn Giác Xi tộc","chucVu":"Thành viên","tuChuong":"@c1573","trangThai":"còn sống"},{"ten":"Cự hán mặc da thú","chucVu":"Thành viên","tuChuong":"@c1573","trangThai":"tử vong"}],"capNhatToi":"@c1573","tabs":{"tienTrinh":[{"chuong":"@c1573","loai":"khai chiến","importance":"normal","giaiDoan":"Vây đánh Hàn Lập","text":"Đội Luyện Hư được truyền tống tới đối phó Hàn Lập nhưng mất cự hán mặc da thú và lão ẩu trong giao chiến.","anchor":"vì một gã Hóa thần kỳ mà điều động nhiều tồn tại Luyện Hư kỳ như vậy","trangThaiMoc":"Tổn thất hai thành viên"}]},"nguon":["@c1573"]},{"id":"thach-kien-toc","name":"Thạch Kiền tộc","cn":"","type":"chung-toc","typeLabel":"Thế lực dị tộc","diaBan":"Thiên Vân","nhanVatChinh":["Chủ nhân khách sạn","Thiết Kiến","Hàn Lập","Thạch Côn","Đoạn Thiên Nhận"],"blurb":"Thạch Kiền tộc là một tộc thuộc khu vực Thiên Vân, nổi bật về luyện khí và thân thể cường đại. Tộc này từng hợp tác với Vạn Cổ tộc chế tạo hệ thống Vân Thành chi vệ, đồng thời nhiều lần nhờ Hàn Lập tìm kiếm tài liệu và khoáng thạch quan trọng tại Nghiễm Hàn Giới.","detail":"Thạch Kiền tộc cùng Vạn Cổ tộc chế tạo hệ thống Vân Thành chi vệ để phòng ngự Vân Thành (@c1576). Tộc này có nhu cầu đối với những tài liệu luyện khí và khoáng thạch quan trọng chỉ có tại Nghiễm Hàn Giới, từng yêu cầu Hàn Lập tìm kiếm chúng (@c1590, @c1726). Ngoài năng lực luyện khí, thân thể của tộc nhân Thạch Kiền tộc còn nổi tiếng cường đại; ngay ở cảnh giới thượng tộc, uy lực đã được đánh giá là đáng sợ (@c1672).","tranPhai":["Vân Thành chi vệ"],"quanHe":"Hợp tác với Vạn Cổ tộc trong việc chế tạo Vân Thành chi vệ.","trangThai":"Đang tìm kiếm khoáng thạch đặc thù","capNhatToi":"@c1576","tabs":{"tienTrinh":[{"chuong":"@c1576","loai":"nhắc tới","importance":"normal","giaiDoan":"Hợp tác chế tạo","text":"Thạch Kiền tộc cùng Vạn Cổ tộc chế tạo hệ thống Vân Thành chi vệ.","anchor":"Chúng được Vạn cổ tộc chúng ta và Thạch Kiền Tộc"},{"chuong":"@c1590","loai":"nhắc tới","importance":"normal","giaiDoan":"Đặt điều kiện truyền tống","text":"Thạch Kiến Tộc yêu cầu Hàn Lập tìm một loại tài liệu luyện khí tại Nghiễm Hàn Giới để đổi lấy quyền sử dụng truyền tống trận.","anchor":"chỉ có Thạch Kiến Tộc là có chút phiền phức"},{"chuong":"@c1672","loai":"nhắc tới","importance":"normal","giaiDoan":"Thể hiện sức mạnh chủng tộc","text":"Liễu Thuý Nhi nhận xét thân thể Thạch Kiến Tộc nổi tiếng cường đại, cảnh giới thượng tộc mà uy lực đã đáng sợ, khi chứng kiến Thạch Côn một quyền san bằng đảo nhỏ.","anchor":"thân thể Thạch Kiến Tộc nổi tiếng cường đại nhưng cảnh giới thượng tộc mà đã có uy lực đáng sợ như vậy"},{"chuong":"@c1726","loai":"nhắc tới","importance":"normal","giaiDoan":"Tìm kiếm khoáng thạch","text":"Thạch Kiến Tộc nhờ Hàn Lập tìm loại khoáng thạch quan trọng chỉ có tại Nghiễm Hàn Giới.","anchor":"loại tài liệu này đối với Thạch Kiến Tộc cũng có chút trọng yếu","trangThaiMoc":"Đang chờ Hàn Lập thu thập khoáng thạch"}]},"nguon":["@c1576","@c1578","@c1590","@c1604","@c1672","@c1694","@c1726"],"thanhVien":[{"ten":"Chủ nhân khách sạn","chucVu":"Chủ nhân khách sạn","tuChuong":"@c1578","trangThai":"đang hoạt động"},{"ten":"Thiết Kiến","chucVu":"Thành viên","tuChuong":"@c1590","trangThai":"đang hoạt động"},{"ten":"Thạch Côn","chucVu":"","tuChuong":"@c1694","trangThai":"Thành viên"},{"ten":"Đoạn Thiên Nhận","chucVu":"","tuChuong":"@c1726","trangThai":"Thành viên"}],"uyLuc":"Tộc nhân ở cảnh giới thượng tộc đã có thân thể với uy lực được nhận xét là đáng sợ (@c1672).","dacDiem":"Giỏi luyện khí, có khả năng chế tạo khí cụ phòng ngự thành thị và nổi tiếng với thân thể cường đại.","congNang":["Hợp tác với Vạn Cổ tộc chế tạo hệ thống Vân Thành chi vệ dùng để phòng ngự Vân Thành (@c1576).","Tộc nhân có thân thể nổi tiếng cường đại (@c1672)."]},{"id":"da-toc","name":"Dạ Tộc","cn":"","aliases":[],"type":"dai-toc","typeLabel":"Đại tộc","diaBan":"Phụ cận Thiên Vân","nhanVatChinh":[],"blurb":"Dạ Tộc là một đại tộc có thực lực mạnh trong khu vực quanh Thiên Vân.","detail":"Giáp Thiên Mộc cho biết thực lực của Dạ Tộc không kém Giác Xi Tộc.","nguon":["@c1577"],"quyMo":"Đại tộc","capNhatToi":"@c1577","tabs":{"tienTrinh":[{"chuong":"@c1577","loai":"nhắc tới","importance":"normal","giaiDoan":"Được giới thiệu là đại tộc quanh Thiên Vân","text":"Dạ Tộc được Giáp Thiên Mộc giới thiệu là đại tộc có thực lực không kém Giác Xi Tộc.","anchor":"còn có Dạ Tộc thực lực không hề kém"}]}},{"id":"bao-minh-toc","name":"Bạo Minh tộc","cn":"","type":"tộc","typeLabel":"Tộc","diaBan":"","nhanVatChinh":[],"blurb":"Đại tộc được nhắc đến vì gần đây không xây dựng truyền tống trận liên đại lục.","detail":"Bạo Minh tộc là đại tộc được Hướng Chi Lễ nói rằng gần đây không xây dựng truyền tống trận liên đại lục.","nguon":["@c1578"]},{"id":"tinh-toc","name":"Tinh tộc","cn":"","type":"toc-toc","typeLabel":"Thế lực","diaBan":"Vân Thành","nhanVatChinh":["Nữ tử Tinh tộc","Thải Lưu Anh","Tiêm Tiêm","Liễu Thuý Nhi"],"blurb":"Tinh tộc là một trong Thiên Vân mười ba tộc, dân số không quá trăm vạn. Tộc nhân có tuổi thọ dài, trí tuệ cao và đặc biệt nổi bật trong luyện đan, trận pháp cùng phù lục; các luyện đan tông sư của tộc còn nắm giữ cách điều chế Vạn Diệu Đan.","detail":"Tinh tộc được giới thiệu qua Thải Lưu Anh trong cuộc tìm kiếm người sở hữu Nguyên Từ Thần Quang @c1594. Tuy thể chất không mạnh như nhiều dị tộc khác, tộc nhân Tinh tộc thường tuấn mỹ, có tuổi thọ gấp ba bốn lần các tộc khác và dễ đạt thành tựu trong luyện đan, trận pháp, phù lục. Tinh Nguyệt Dịch là vật phẩm gắn với Tinh tộc, từng được Liễu Thuý Nhi đề nghị dùng để đổi lấy Hư Linh đan @c1709; ngoài ra, cách điều chế Vạn Diệu Đan chỉ do luyện đan tông sư của Tinh tộc nắm giữ @c1744.","nguon":["@c1579","@c1594","@c1635","@c1670","@c1709","@c1744"],"tabs":{"tienTrinh":[{"chuong":"@c1594","loai":"nhắc tới","importance":"normal","giaiDoan":"Tìm được người thứ ba có Nguyên Từ Thần Quang","text":"Tinh Tộc được giới thiệu qua Thải Lưu Anh trong cuộc tìm kiếm người sở hữu Nguyên Từ Thần Quang.","anchor":"Tinh Tộc mỹ phu nhân nhìn bàn tay này, nhíu mày"},{"chuong":"@c1709","loai":"nhắc tới","importance":"normal","giaiDoan":"Dùng trấn tộc chi bảo trao đổi","text":"Liễu Thuý Nhi đề nghị dùng một lọ Tinh Nguyệt Dịch của Tinh Tộc để đổi lấy Hư Linh đan.","anchor":"đem trấn tộc chi bảo của Tinh Tộc chúng ta, Tinh Nguyệt Dịch tặng cho một lọ"},{"chuong":"@c1744","loai":"nhắc tới","importance":"bridge","giaiDoan":"Bí truyền được xác nhận","text":"Thải Lưu Anh xác nhận cách điều chế Vạn Diệu Đan chỉ do luyện đan tông sư của Tinh Tộc nắm giữ.","anchor":"cách điều chế Vạn Diệu Đan chỉ có luyện đan tông sư của Tinh Tộc chúng ta mới có thể nắm giữ.","trangThaiMoc":"Nắm giữ bí truyền luyện đan"}]},"thanhVien":[{"ten":"Thải Lưu Anh","chucVu":"Hợp Thể kỳ","tuChuong":"@c1594","trangThai":"Đang hoạt động"},{"ten":"Tiêm Tiêm","chucVu":"Không rõ","tuChuong":"@c1635","trangThai":"thành viên"},{"ten":"Liễu Thủy Nhi","chucVu":"Đệ tử của Thải Lưu Anh","tuChuong":"@c1709","trangThai":"Đang hoạt động"}],"trangThai":"Không rõ","dacDiem":"Dân số không quá trăm vạn; thể chất không mạnh như nhiều dị tộc khác, nhưng tộc nhân tuấn mỹ, trí tuệ cao và có tuổi thọ gấp ba bốn lần các tộc khác.","congNang":["Tộc nhân dễ đạt thành tựu trong các lĩnh vực luyện đan, trận pháp và phù lục.","Các luyện đan tông sư của Tinh tộc nắm giữ cách điều chế Vạn Diệu Đan @c1744."]},{"id":"thien-van-toc","name":"Thiên Vân Tộc","cn":"","type":"toc","typeLabel":"Chủng tộc","diaBan":"Thiên Vân","nhanVatChinh":["Tư lão"],"blurb":"Các thánh tộc lục, thất giai của Thiên Vân Tộc từng liên thủ tiến vào Ma Kim Sơn Mạch.","detail":"Sau khi tiến vào trung tâm Ma Kim Sơn Mạch, các thánh tộc đỉnh giai của Thiên Vân Tộc phong tỏa khu vực, chỉ để lại một lối vào và quy định thời hạn tiến nhập đối với những người ngoài thánh tộc.","thanhVien":[{"ten":"Các thánh tộc lục, thất giai","chucVu":"Thành phần tiến vào Ma Kim Sơn Mạch","tuChuong":"@c1581","trangThai":"đang hoạt động"},{"ten":"Tư lão","chucVu":"","tuChuong":"@c1728","trangThai":"thành viên"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1581","nguon":["@c1581","@c1728"]},{"id":"da-thu-toc","name":"Đa Thủ Tộc","cn":"","type":"tộc","typeLabel":"Tộc","diaBan":"","nhanVatChinh":[],"blurb":"Đa Thủ Tộc là một trong bốn tộc cùng phụ trách truyền tống trận đến đại lục.","detail":"Đa Thủ Tộc cùng Tinh Tộc, Thạch Kiến Tộc và Vạn Cổ Tộc cử người trông coi, bảo vệ và tu sửa truyền tống trận.","thanhVien":[],"tabs":{"tienTrinh":[{"chuong":"@c1583","loai":"nhắc tới","importance":"normal","giaiDoan":"Đồng quản lý truyền tống trận.","trangThaiMoc":"đồng quản lý truyền tống trận","text":"Đa Thủ Tộc được xác nhận là một trong các tộc cùng trông coi và tu sửa truyền tống trận đến đại lục.","anchor":"do Tinh Tộc, Thạch Kiến Tộc, Đa Thủ Tộc, cùng với Vạn Cổ Tộc chúng ta trông coi"}]},"nguon":["@c1583"]},{"id":"chap-phap-ve-doi-tay-thanh-van-thanh","name":"Chấp pháp vệ đội Tây thành Vân thành","cn":"","type":"doi-ngu","typeLabel":"Đội chấp pháp","diaBan":"Tây thành Vân thành","nhanVatChinh":["Bạch trưởng lão","Giáp sĩ chấp pháp vệ đội Tây thành"],"blurb":"Chấp pháp vệ đội Tây thành Vân thành chịu trách nhiệm điều tra động tĩnh bất thường trong khu vực.","detail":"Các pháp sĩ mặc hắc sắc chiến giáp của đội xuất hiện tại phòng Hàn Lập sau khi Nghiễm Hàn Lệnh phóng cột sáng. Họ chất vấn việc kích hoạt bảo vật uy lực lớn trong Vân thành.","thanhVien":[{"ten":"Bạch trưởng lão","chucVu":"Trưởng lão","tuChuong":"@c1585","trangThai":"dang-hoat-dong"},{"ten":"Giáp sĩ chấp pháp vệ đội Tây thành","chucVu":"Giáp sĩ chấp pháp","tuChuong":"@c1585","trangThai":"dang-hoat-dong"}],"trangThai":"dang-hoat-dong","nguon":["@c1585"]},{"id":"thuy-mi-toc","name":"Thủy Mị Tộc","cn":"","type":"toc","typeLabel":"Tộc","diaBan":"","nhanVatChinh":["Bạch Nga"],"blurb":"Thủy Mị Tộc do Bạch Nga đại diện muốn mời Hàn Lập làm khách khanh.","detail":"Thủy Mị Tộc muốn dựa vào Nghiễm Hàn Lệnh để đưa người trong tộc tiến vào Nghiễm Hàn Giới. Bạch Nga chính thức đưa ra lời mời và hứa giúp Hàn Lập tăng một giai tu vi trong vòng trăm năm.","thanhVien":[{"ten":"Bạch Nga","chucVu":"Trưởng lão","tuChuong":"@c1586","trangThai":"dang-giu-chuc"}],"capNhatToi":"@c1586","tabs":{"tienTrinh":[{"chuong":"@c1586","loai":"nhắc tới","importance":"normal","giaiDoan":"Tranh quyền mời Hàn Lập","text":"Thủy Mị Tộc do Bạch Nga đại diện mời Hàn Lập làm khách khanh vì liên quan đến Nghiễm Hàn Lệnh.","anchor":"chỉ cần đạo hữu đồng ý gia nhập Thủy Mị Tộc"}]},"nguon":["@c1586"]},{"id":"am-yeu-toc","name":"Âm Yêu Tộc","cn":"","type":"toc","typeLabel":"Tộc","diaBan":"","nhanVatChinh":["Thương Ảnh"],"blurb":"Âm Yêu Tộc do Thương Ảnh đại diện cũng muốn giành quyền mời Hàn Lập làm khách khanh.","detail":"Thương Ảnh cho rằng Âm Yêu Tộc có quyền mời Hàn Lập, nhưng cuộc tranh chấp bị Thiên Cơ Tử áp đảo.","thanhVien":[{"ten":"Thương Ảnh","chucVu":"Đại diện","tuChuong":"@c1586","trangThai":"hoat-dong"}],"capNhatToi":"@c1586","tabs":{"tienTrinh":[{"chuong":"@c1586","loai":"nhắc tới","importance":"normal","giaiDoan":"Tranh quyền mời Hàn Lập","text":"Âm Yêu Tộc thông qua Thương Ảnh tranh quyền mời Hàn Lập làm khách khanh.","anchor":"nói không chừng là nguyên ý đảm nhận chức khách khanh của Âm Yêu Tộc chúng ta"},{"chuong":"@c1665","loai":"nhắc tới","importance":"normal","giaiDoan":"Tham gia cuộc họp truy gián điệp","text":"Thương Ảnh đại diện Âm Yêu Tộc tham gia cuộc họp, thừa nhận kém ba bước về Mê Hồn Thuật so với tộc Bạch đạo hữu.","anchor":"Âm Yêu tộc chúng ta làm kính nhường quý tộc thiên phú ba bước"}]},"nguon":["@c1586","@c1665"]},{"id":"muoi-ba-toc","name":"Mười ba tộc","cn":"","type":"lien-minh","typeLabel":"Liên minh các tộc","diaBan":"","nhanVatChinh":[],"blurb":"Mười ba tộc có quy tắc bất thành văn về thứ tự mời ngoại tộc nhân làm khách khanh.","detail":"Quy tắc này quy định tộc nhìn thấy ngoại tộc nhân trước có quyền mời trước, nhưng việc Hàn Lập sở hữu Nghiễm Hàn Lệnh khiến trình tự khó được bảo đảm.","nguon":["@c1586"]},{"id":"cac-toc-ung-ho-nguoi-vao-nghiem-han-gioi","name":"Các tộc ủng hộ người tiến vào Nghiễm Hàn Giới","cn":"","aliases":[],"type":"lien-minh","typeLabel":"Thế lực chống lưng","diaBan":"Không xác định","nhanVatChinh":[],"blurb":"Những tộc có đủ thế lực để đứng sau người sử dụng Nghiễm Hàn Lệnh. Chương chưa xác định tên cụ thể của các tộc này.","detail":"Muốn sử dụng Nghiễm Hàn Lệnh để tiến vào Nghiễm Hàn Giới, người giữ lệnh phải có ít nhất một tộc đứng phía sau ủng hộ.","tonChi":"Ủng hộ người sử dụng Nghiễm Hàn Lệnh tiến vào Nghiễm Hàn Giới","trangThai":"Không xác định","capNhatToi":"@c1587","tabs":{"tienTrinh":[{"chuong":"@c1587","loai":"nhắc tới","importance":"normal","giaiDoan":"Điều kiện sử dụng Nghiễm Hàn Lệnh","text":"Thiên Cơ Tử tiết lộ người muốn tiến vào Nghiễm Hàn Giới phải được một tộc đứng phía sau ủng hộ.","anchor":"nếu không có một tộc nào đó đứng ở phía sau ủng hộ","trangThaiMoc":"Chưa xác định tộc cụ thể"}]},"nguon":["@c1587"]},{"id":"tu-toc-dau-gia-hoi","name":"Tứ Tộc Đấu Giá Hội","cn":"","type":"to-chuc-su-kien","typeLabel":"Hội đấu giá","diaBan":"Vân thành","nhanVatChinh":["Thiết Kiến"],"blurb":"Hội đấu giá do Thạch Kiến Tộc chủ trì, được tổ chức định kỳ để tăng sức hút cho Vân thành.","detail":"Kỳ đấu giá này tăng số lượng bảo vật quý hiếm do ảnh hưởng của chiến sự với Giác Xi Tộc, trong đó có khả năng xuất hiện Vạn Diệu Đan và hai thông linh khôi lỗi của Vạn Cổ Tộc.","nguonGoc":"Được tổ chức định kỳ mười năm một lần.","lanhDaoHienThoi":"Thạch Kiến Tộc","quyMo":"Quy tụ nhiều tu sĩ cấp cao và bảo vật quý hiếm.","quanHe":"Có sự tham gia của bốn tộc tại Vân thành.","trangThai":"đang tổ chức","capNhatToi":"@c1590","tabs":{"tienTrinh":[{"chuong":"@c1590","loai":"nhắc tới","importance":"normal","giaiDoan":"Kỳ đấu giá thời chiến","text":"Tứ Tộc Đấu Giá Hội được tăng cường vật phẩm quý hiếm sau chiến sự với Giác Xi Tộc.","anchor":"Tứ tộc đấu giá hội này so với mười ba tộc chúng ta cách mười năm tổ chức một lần"}]},"nguon":["@c1590"]},{"id":"dau-gia-hoi-van-thanh","name":"Đấu giá hội Vân thành","cn":"","type":"to-chuc","typeLabel":"Tổ chức đấu giá","diaBan":"Vân thành","nhanVatChinh":["Hàn Lập"],"blurb":"Đấu giá hội Vân thành tổ chức khu giám định và cuộc đấu giá trong đại điện.","detail":"Đấu giá hội có khu giám định riêng, ba giám định viên, thị vệ và thính đường ba tầng. Hội chỉ xem xét bảo vật hàng đầu tại đại điện, còn vật phẩm chất kém được hướng sang thiên điện bên cạnh.","nguon":["@c1596"]},{"id":"sa-toc","name":"Sa Tộc","cn":"","type":"tộc","typeLabel":"Tộc","diaBan":"Vân thành","nhanVatChinh":["Tiêu Bố Y"],"blurb":"Sa Tộc phụ trách tứ tộc đấu giá hội lần này tại Vân thành. Tiêu Bố Y đại diện Sa Tộc đứng ra chủ trì đấu giá.","detail":"Tiêu Bố Y cho biết vì ông thuộc Sa Tộc nên tứ tộc đấu giá hội lần này do ông chủ trì.","nguon":["@c1597"],"thanhVien":[{"ten":"Tiêu Bố Y","chucVu":"Người chủ trì đấu giá","tuChuong":"@c1597","trangThai":"đang tại vị"}],"tabs":{"tienTrinh":[{"chuong":"@c1597","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Phụ trách tứ tộc đấu giá hội","trangThaiMoc":"đang phụ trách đấu giá hội","text":"Sa Tộc phụ trách tứ tộc đấu giá hội lần này tại Vân thành.","anchor":"Lúc này đây, tứ tộc đấu giá hội bởi vì tại hạ ở trong Sa Tộc, cho nên đấu giá hội lần này do ta chủ trì."}]}},{"id":"muoi-ba-toc-van-thanh","name":"Mười ba tộc Vân thành","cn":"","type":"liên minh cộng cư","typeLabel":"Liên minh cộng cư","diaBan":"Vân thành","nhanVatChinh":[],"blurb":"Mười ba tộc cùng sinh sống tại Vân thành và tạo nên lực lượng cường giả đông đảo. Quy mô cường giả Hợp Thể kỳ tại đây khiến Hàn Lập kinh hãi.","detail":"Các tộc cộng cư ở Vân thành khiến đại điện đấu giá quy tụ rất nhiều tu sĩ từ Nguyên Anh kỳ trở lên, trong đó có sáu, bảy mươi cường giả Hợp Thể kỳ tại các phòng tầng ba.","nguon":["@c1597"]},{"id":"bon-khach-khanh-van-thanh","name":"Bốn khách khanh Vân thành","cn":"","type":"nhom-khach-khanh","typeLabel":"Nhóm khách khanh","diaBan":"Vân thành","nhanVatChinh":["Lam huynh","Giáp sĩ cao lớn mang mặt nạ vàng","Sửu phụ có bích lục lân phiến","Quái nhân hai đầu"],"blurb":"Nhóm bốn cường giả Hợp Thể Trung Kỳ được Vân thành mời tới bảo đảm phần đấu giá áp trục.","detail":"Bốn khách khanh từng liên thủ bắt giữ dị thú mang huyết mạch Nhân Diện Giao và xuất hiện trên đài đấu giá để giới thiệu vật phẩm áp trục.","nguon":["@c1599"],"quyMo":"4 khách khanh Hợp Thể Trung Kỳ","thanhVien":[{"ten":"Lam huynh","chucVu":"Khách khanh","tuChuong":"@c1599","trangThai":"đang giữ chức"},{"ten":"Giáp sĩ cao lớn mang mặt nạ vàng","chucVu":"Khách khanh","tuChuong":"@c1599","trangThai":"đang giữ chức"},{"ten":"Sửu phụ có bích lục lân phiến","chucVu":"Khách khanh","tuChuong":"@c1599","trangThai":"đang giữ chức"},{"ten":"Quái nhân hai đầu","chucVu":"Khách khanh","tuChuong":"@c1599","trangThai":"đang giữ chức"}],"tabs":{"tienTrinh":[{"chuong":"@c1599","loai":"nhắc tới","importance":"normal","giaiDoan":"Bảo đảm đấu giá áp trục","text":"Bốn khách khanh Hợp Thể Trung Kỳ được truyền tống lên đài để tham gia bảo đảm phần đấu giá áp trục.","anchor":"bốn người này là bốn vị khách khanh của Vân thành"}]}},{"id":"bon-toc-to-chuc-dau-gia-hoi","name":"Bốn tộc tổ chức đấu giá hội","cn":"","type":"lien-minh","typeLabel":"Liên minh thế lực","diaBan":["Vân thành"],"nhanVatChinh":["Tiêu Bố Y"],"blurb":"Bốn tộc cùng làm chủ đấu giá hội tại Vân thành. Uy danh của họ được Tiêu Bố Y dùng để trấn an khách dự hội khi cửa điện bị kẻ lạ phá vỡ.","detail":"Thế lực liên hợp tổ chức đấu giá hội và bố trí thủ vệ tại Vân thành. Đấu giá hội bị một nam tử bí ẩn công kích trực tiếp khi cấm chế cửa đại điện bị đánh vỡ.","trangThai":"hoat-dong","nguon":["@c1600"]},{"id":"dia-linh-toc","name":"Địa Linh Tộc","cn":"","type":"toc","typeLabel":"Tộc","diaBan":"Lôi Minh Đại Lục","nhanVatChinh":[],"blurb":"Địa Linh Tộc đã diệt vong, từng được xem là tộc đứng đầu về chế tạo khôi lỗi ở Lôi Minh Đại Lục.","detail":"Địa Linh Tộc bị diệt từ hàng chục vạn năm trước và là nguồn gốc của bộ Địa U chiến xa.","trangThai":"diệt","nguon":["@c1603"]},{"id":"u-toc-bi-mat-suy-bai","name":"U tộc bí mật đã suy bại","cn":"","type":"toc","typeLabel":"Tộc","diaBan":"","nhanVatChinh":[],"blurb":"Một nhánh U tộc bí mật đã suy bại, nơi bộ Địa U chiến xa được phát hiện.","detail":"Tiêu Bố Y cho biết Địa U chiến xa được tìm thấy tại một nhánh U tộc bí mật đã suy bại, nhưng không nêu thêm tình hình cụ thể.","trangThai":"suy-bai","nguon":["@c1603"]},{"id":"ma-kim-son-mach","name":"Ma Kim Sơn mạch","cn":"","type":"dia-ban","typeLabel":"Địa bàn","diaBan":"Ma Kim Sơn mạch","nhanVatChinh":["Việt Tông"],"blurb":"Ma Kim Sơn mạch là địa vực nhóm Hàn Lập dự định tiến vào sau khi Nghiễm Hàn Giới mở ra.","detail":"Tiêm Tiêm cho biết Việt Tông là thợ săn ma thú nổi tiếng nhất tại Ma Kim Sơn mạch và nhóm Hàn Lập cần mượn thần thông của hắn để thuận lợi tiến vào nơi này.","nguon":["@c1605"]},{"id":"viet-tong-tai-ma-kim-son-mach","name":"Việt Tông tại Ma Kim Sơn Mạch","cn":"","type":"the-luc","typeLabel":"Thế lực và liên hệ cá nhân","diaBan":"Ma Kim Sơn Mạch","nhanVatChinh":["Việt Tông"],"blurb":"Việt Tông có danh tiếng lớn tại Ma Kim Sơn Mạch và được nhiều tu sĩ nhận biết.","detail":"Nhiều tu sĩ chủ động chào hỏi Việt Tông, trong khi một số người khác trở nên cảnh giác khi nghe tên hắn.","nguon":["@c1608"]},{"id":"loi-van-cac","name":"Lôi Vân Các","cn":"","type":"co-so","typeLabel":"Cơ sở quản lý","diaBan":"Vụ hải bên ngoài Ma Kim Sơn Mạch","nhanVatChinh":[],"blurb":"Lôi Vân Các là lầu các cấp cấm chế lệnh bài và vật phẩm cho người tiến vào Ma Kim Sơn Mạch.","detail":"Tầng ba Lôi Vân Các tập trung hơn ba mươi tu sĩ và có người phụ trách trông coi.","nguon":["@c1608"]},{"id":"loi-van-dai-tran","name":"Lôi Vân Đại Trận","cn":"","type":"tran-phap","typeLabel":"Trận pháp phòng hộ","diaBan":"Lối vào Ma Kim Sơn Mạch","nhanVatChinh":[],"blurb":"Lôi Vân Đại Trận là hệ thống cấm chế phát ra thần lôi để bảo vệ lối vào Ma Kim Sơn Mạch.","detail":"Chi Tiên đã xuyên qua Vạn Lôi Áp Đỉnh thuộc Lôi Vân Đại Trận để tiến vào sơn mạch.","trangThai":"đang bảo vệ lối vào","nguon":["@c1608"]},{"id":"truong-lao-hoi-loi-van-tran","name":"Trưởng lão hội Lôi Vân Trấn","cn":"","type":"Thế lực quản lý","typeLabel":"Trưởng lão hội","diaBan":"Lôi Vân Trấn","nhanVatChinh":["Mẫn chấp sự"],"blurb":"Cơ quan quản lý và duy trì quy củ tại Lôi Vân Trấn, có quyền xử lý những người gây rối hoặc vi phạm quy định.","detail":"Trưởng lão hội có quyền hủy tư cách tiến vào Ma Kim Sơn Mạch và trục xuất người gây rối khỏi Lôi Vân Trấn. Mẫn chấp sự đại diện cơ quan này ngăn đấu pháp trong Lôi Vân Các, đồng thời phụ trách công bố và tổ chức quy trình kiểm tra người muốn tiến vào sơn mạch.","nguon":["@c1610"]},{"id":"loi-van-tran","name":"Lôi Vân Trấn","cn":"","type":"Thế lực kiêm khu vực quản lý","typeLabel":"Trấn","diaBan":"Lôi Vân Trấn","nhanVatChinh":["Mẫn chấp sự"],"blurb":"Khu vực có quy củ riêng để quản lý tranh chấp và người muốn tiến vào Ma Kim Sơn Mạch.","detail":"Tranh chấp tại Lôi Vân Trấn phải được giải quyết bằng đấu pháp giữa những người có tu vi tương đương tại nơi chuyên dụng. Việc tự ý giao chiến trong Lôi Vân Các bị cấm; người vi phạm có thể mất tư cách tiến vào Ma Kim Sơn Mạch và bị đuổi khỏi trấn.","nguon":["@c1610"]},{"id":"loi-van-quy","name":"Lôi Vân Quỹ","cn":"","aliases":[],"type":"the-luc","typeLabel":"Thế lực","diaBan":"Ma Kim Sơn Mạch","nhanVatChinh":[],"blurb":"Một nhóm người thuộc Lôi Vân Quỹ tiến vào Ma Kim Sơn Mạch cùng các toán tu luyện giả khác rồi tản ra.","detail":"Người của Lôi Vân Quỹ tiến vào sơn mạch trong thời gian các đội ngũ lần lượt vượt qua cửa vào, sau đó phân tán trong khu vực này.","nguon":["@c1612"]},{"id":"nguoi-linh-gioi","name":"Người Linh giới","cn":"","type":"nhom","typeLabel":"Nhóm tu luyện giả","diaBan":"Ma Kim Sơn mạch","nhanVatChinh":["Ba lam bào nhân"],"blurb":"Người Linh giới là nhóm tiến vào Ma Kim Sơn mạch vì mục tiêu liên quan đến Hóa hình Ma tiêu và Chi tiên.","detail":"Cự sí nam tử cho phép thuộc hạ bí mật giết những người Linh giới gặp trên đường, nhưng không được gây thương vong quá lớn đến mức phá vỡ ước định với các tồn tại đỉnh giai.","nguon":["@c1615"],"trangThai":"dang-hoat-dong","thanhVien":[{"ten":"Ba lam bào nhân","chucVu":"Tu luyện giả","tuChuong":"@c1615","trangThai":"tu-vong"}]},{"id":"thu-ha-cua-da-nhan","name":"Thủ hạ của Đa Nhãn","cn":"","type":"phe-the-luc","typeLabel":"Phe ma thú","diaBan":"Ma Kim Sơn mạch","nhanVatChinh":["Đa Nhãn Ma"],"blurb":"Thủ hạ của Đa Nhãn là một phe hoạt động tại Ma Kim Sơn mạch. Cự sí nam tử muốn che giấu chiến dịch bí mật tìm Chi tiên với phe này.","detail":"Phe này được nhắc đến như nhóm mà Cự sí nam tử không muốn biết việc mình huy động ma thú tìm Chi tiên.","nguon":["@c1615"],"trangThai":"dang-hoat-dong"},{"id":"thu-ha-cua-huyet-ti","name":"Thủ hạ của Huyết Ti","cn":"","type":"phe-the-luc","typeLabel":"Phe ma thú","diaBan":"Ma Kim Sơn mạch","nhanVatChinh":["Huyết Ti"],"blurb":"Thủ hạ của Huyết Ti là một phe hoạt động tại Ma Kim Sơn mạch. Cự sí nam tử muốn che giấu chiến dịch bí mật tìm Chi tiên với phe này.","detail":"Phe này được nhắc đến cùng thủ hạ của Đa Nhãn như nhóm không được biết kế hoạch triệu tập ma thú tìm Chi tiên.","nguon":["@c1615"],"trangThai":"dang-hoat-dong"},{"id":"dai-quan-ma-thu-duoi-quyen-cu-thu","name":"Đại quân ma thú dưới quyền Cự Thử","cn":"","type":"quan-doi-ma-thu","typeLabel":"Đại quân ma thú","diaBan":"Ma Kim Sơn Mạch và khu vực ngoại vi","nhanVatChinh":["Cự Thử","Thiết Ma đại nhân"],"blurb":"Đại quân gồm hơn một ngàn ma thú đã khai mở linh trí, được Cự Thử tập hợp để săn giết người ngoại lai. Theo mệnh lệnh, chúng tiến ra ngoại vi Ma Kim Sơn Mạch, đồng thời truy tìm Chi tiên để dâng cho Thiết Ma.","detail":"Đây là lực lượng ma thú dưới quyền Cự Thử, quy tụ hơn một ngàn cá thể đã khai mở linh trí. Đại quân được lệnh giết sạch người ngoại lai, đoạt thanh bàn pháp khí, tìm kiếm Chi tiên và dâng linh vật này cho Thiết Ma; sau khi tập hợp, chúng phân tán tiến về khu vực ngoại vi Ma Kim Sơn Mạch để thi hành nhiệm vụ. @c1619","nguon":["@c1619"],"quyMo":"Hơn một ngàn ma thú","lanhDaoHienThoi":"Cự Thử","trangThai":"mở cuộc săn giết người ngoại lai","thanhVien":[{"ten":"Cự Thử","chucVu":"Chỉ huy cuộc tập hợp","tuChuong":"@c1619","trangThai":"đang chỉ huy"}],"tabs":{"tienTrinh":[{"chuong":"@c1619","loai":"khai chiến","importance":"major","giaiDoan":"Phát động cuộc săn giết","text":"Đại quân ma thú được lệnh tiến ra ngoại vi để giết người ngoại lai và tìm Chi tiên.","anchor":"Hơn một ngàn đầu ma thú ở đây đều đã mở ra lính trí, sau khi nghe xong thì lập tức giải tán"}]},"dacDiem":"Gồm hơn một ngàn ma thú đã khai mở linh trí, chịu sự điều động của Cự Thử.","congNang":["Săn giết người ngoại lai tại ngoại vi Ma Kim Sơn Mạch. @c1619","Đoạt thanh bàn pháp khí của người ngoại lai.","Tìm kiếm Chi tiên để dâng cho Thiết Ma. @c1619","Phân tán lực lượng tiến ra khu vực ngoại vi Ma Kim Sơn Mạch."]},{"id":"ma-thu","name":"Ma thú","cn":"","type":"quan-the","typeLabel":"Quần thể","diaBan":"","nhanVatChinh":["Cửu Dạ","Ma Yên Điểu","Mặc Kỳ lân"],"blurb":"Ma thú là quần thể gồm các cá thể có thể hóa hình, trong đó Cửu Dạ là ma thú hình người.","detail":"Chương đề cập Cửu Dạ và một ma thú thánh giai đang bị Hàn Lập chuẩn bị đối phó.","nguon":["@c1621"]},{"id":"doi-ma-thu-truy-kich-cua-da-nhan-ma","name":"Đội ma thú truy kích của Đa Nhãn ma","cn":"","type":"doi-quan","typeLabel":"Đội ma thú","diaBan":"Ma Kim Sơn Mạch","nhanVatChinh":["Đa Nhãn ma","Ngũ Khấp"],"blurb":"Đội ma thú do Đa Nhãn ma tập hợp và giao Ngũ Khấp dẫn đường truy kích.","detail":"Đội quân gồm hàng trăm hóa hình ma thú lần theo dấu hiệu Cửu Dạ để lại nhằm truy đuổi Hàn Lập và Tiêm Tiêm.","nguon":["@c1638"]},{"id":"nhom-nam-ma-thu-truy-kich","name":"Nhóm năm ma thú truy kích","cn":"","type":"nhom-ma-thu","typeLabel":"Nhóm ma thú","diaBan":"Ma Kim Sơn Mạch","nhanVatChinh":["Lưu ly tiểu thú","Mãng thú","Ma thú còn lại trong nhóm truy tìm"],"blurb":"Nhóm ma thú đang truy tìm Hàn Lập trong Ma Kim Sơn Mạch, do Lưu ly tiểu thú đưa ra kế hoạch hành động.","detail":"Sau khi mất dấu Hàn Lập, nhóm quyết định quay về hội hợp thêm đồng loại rồi kéo đến lối ra Ma Kim Sơn Mạch tổ chức mai phục.","quyMo":"Năm ma thú hiện diện","lanhDaoHienThoi":"Lưu ly tiểu thú","trangThai":"Đang chuẩn bị mai phục Hàn Lập","thanhVien":[{"ten":"Lưu ly tiểu thú","chucVu":"Người đề xuất kế hoạch","tuChuong":"@c1644","trangThai":"Đang hoạt động"},{"ten":"Mãng thú","chucVu":"Thành viên","tuChuong":"@c1644","trangThai":"Đang hoạt động"},{"ten":"Ma thú còn lại trong nhóm truy tìm","chucVu":"Thành viên","tuChuong":"@c1644","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1644","tabs":{"tienTrinh":[{"chuong":"@c1644","loai":"khai chiến","importance":"normal","giaiDoan":"Chuẩn bị mai phục","trangThaiMoc":"Hội hợp đồng loại và tiến về lối ra","text":"Nhóm chấp nhận kế hoạch quay về hội hợp thêm ma thú rồi tổ chức mai phục Hàn Lập tại lối ra Ma Kim Sơn Mạch.","anchor":"Sau khi trở về tụ tập cùng những người khác"}]},"nguon":["@c1644"]},{"id":"nhom-ba-ma-dau-tran-giu-ma-kim-son-mach","name":"Nhóm ba ma đầu trấn giữ Ma Kim Sơn Mạch","cn":"","type":"the-luc","typeLabel":"Nhóm ma đầu","diaBan":"Ma Kim Sơn Mạch","nhanVatChinh":["Thiết huynh","Huyết Tí","Đa Nhãn"],"blurb":"Nhóm ba ma đầu cùng phụng sự một Thánh tổ và quản lý Ma Kim Sơn Mạch.","detail":"Nhóm gồm Thiết huynh, Huyết Tí và Đa Nhãn. Họ chờ Thánh tổ thức tỉnh để quyết định việc xử lý Hắc Uyên ngạc, đồng thời dò xét nhau quanh chuyện Chi tiên.","thanhVien":[{"ten":"Thiết huynh","chucVu":"Ma đầu trấn giữ sơn mạch","tuChuong":"@c1649","trangThai":"đang giữ vị trí"},{"ten":"Huyết Tí","chucVu":"Ma đầu trấn giữ sơn mạch","tuChuong":"@c1649","trangThai":"đang giữ vị trí"},{"ten":"Đa Nhãn","chucVu":"Ma đầu trấn giữ sơn mạch","tuChuong":"@c1649","trangThai":"đang giữ vị trí"}],"lanhDaoHienThoi":"Thánh tổ đại nhân","capBac":"","quyMo":"","trangThai":"đang quản lý Ma Kim Sơn Mạch","nguon":["@c1649"]},{"id":"quan-ma-thu-mai-phuc","name":"Quần ma thú mai phục","cn":"","type":"nhom","typeLabel":"Nhóm ma thú","diaBan":"Thông đạo gần lối ra Ma Kim Sơn Mạch","nhanVatChinh":["Lưu ly tiểu thú","Ma thú giống heo rừng","Cốc lão giả"],"blurb":"Lực lượng gồm hơn trăm ma thú trung và cao giai mai phục trong thông đạo. Nhóm do Lưu ly tiểu thú chỉ huy tại chỗ và tiếp tục chờ bắt người sau khi Hàn Lập cùng Tiêm Tiêm thoát đi.","detail":"Quần ma thú phối hợp ép hắc khí từ hai bên thông đạo để vây đánh Hàn Lập và Tiêm Tiêm nhưng không thành công. Sau thất bại, Lưu ly tiểu thú ra lệnh tiếp tục ẩn nấp tại khu vực phụ cận nhằm bắt những người từ bên ngoài tiến vào và bảo đảm có thể trở về báo cáo.","quyMo":"Hơn trăm ma thú trung và cao giai","lanhDaoHienThoi":"Lưu ly tiểu thú","trangThai":"Tiếp tục mai phục","thanhVien":[{"ten":"Lưu ly tiểu thú","chucVu":"Thủ lĩnh tại chỗ","tuChuong":"@c1652","trangThai":"đang chỉ huy"},{"ten":"Ma thú giống heo rừng","chucVu":"Thành viên","tuChuong":"@c1652","trangThai":"đang tham gia"}],"tabs":{"tienTrinh":[{"chuong":"@c1652","loai":"nhắc tới","importance":"normal","giaiDoan":"Mai phục thất bại","text":"Quần ma thú để Hàn Lập và Tiêm Tiêm thoát khỏi đòn hợp kích nhưng vẫn tiếp tục mai phục để bắt những người khác tiến vào.","anchor":"Nếu không thì không thể nào trở về báo cáo được","trangThaiMoc":"Tiếp tục mai phục"}]},"capNhatToi":"@c1652","nguon":["@c1652"]},{"id":"thap-dai-ma-dau","name":"Thập đại ma đầu","cn":"十大魔頭","type":"nhom-the-luc","typeLabel":"Nhóm thế lực","diaBan":"Không rõ","nhanVatChinh":[],"blurb":"Nhóm mười ma đầu mạnh nhất, tu vi ngang tầm chân linh. Kỳ Lân nghi ngờ thiên ngoại ma giáp thuộc về một trong thập đại ma đầu.","detail":"Kỳ Lân hư ảnh nhắc đến khi nhận định thần niệm ma vật xuyên không gian đoạt ma giáp có tu vi không kém chân linh. Hắn đặt nghi vấn ma giáp có thể là vật của một trong thập đại ma đầu. Đây là lần đầu khái niệm thập đại ma đầu được đề cập trong bối cảnh lai lịch thiên ngoại ma giáp.","nguon":["@c1661"]},{"id":"van-toc","name":"Vân tộc","cn":"云族","type":"bo-toc","typeLabel":"Bộ tộc","diaBan":"Vân Thành","nhanVatChinh":["Hứa lão quái","Hứa Luân Tường"],"blurb":"Vân tộc là một trong Thiên Vân thập tam tộc, nhân số thưa thớt nhưng thực lực chỉnh thể luôn đứng trong ba vị trí đầu. Tộc này nổi danh với thuật ẩn nấp, biến hóa và thiên phú bản mạng Vân thú.","detail":"Vân tộc cùng Tinh tộc là hai chủng tộc có nhân số ít nhất trong Thiên Vân thập tam tộc, song thực lực chỉnh thể của Vân tộc chưa từng rơi khỏi ba vị trí đầu. Thành viên Vân tộc am hiểu ẩn giấu thân phận và biến hóa thành người thuộc tộc khác; tại Vân Thành, nhiều người Vân tộc sinh sống mà không công khai lai lịch, thậm chí giả dạng thành viên chủng tộc khác. Thiên phú cốt lõi của họ là bản mạng Vân thú, một tồn tại vừa mang tính linh thú vừa là hóa thân, có thể hợp nhất với chủ nhân để hóa thành Vân thú cự linh. Hứa lão quái là một thành viên đã tự tiết lộ thân phận Vân tộc và giải thích những đặc trưng này. @c1662","nguonGoc":"Một trong Thiên Vân thập tam tộc","tonChi":"Ẩn giấu thân phận, bảo tồn lực lượng","capBac":"Một trong thập tam tộc, xếp trước ba về thực lực","quyMo":"Nhân số ít nhất cùng Tinh tộc trong thập tam tộc","tranPhai":"Thuật biến hóa ẩn nấp, bản mạng Vân thú","quanHe":"Thuộc Thiên Vân thập tam tộc, nhân số ngang Tinh tộc nhưng mạnh hơn","trangThai":"Đang hưng thịnh","thanhVien":[{"ten":"Hứa lão quái","chucVu":"Thành viên","tuChuong":"@c1662","trangThai":"hoat-dong"},{"ten":"Hứa Luân Tường","chucVu":"Hậu bối","tuChuong":"@c1662","trangThai":"hoat-dong"}],"tabs":{"tienTrinh":[{"chuong":"@c1662","loai":"xuất hiện","importance":"major","giaiDoan":"Lần đầu giới thiệu chi tiết","trangThaiMoc":"Hưng thịnh, top 3 thực lực trong thập tam tộc","text":"Hứa lão quái tiết lộ bản thân thuộc Vân tộc, giải thích về thuật biến hóa ẩn nấp và bản mạng Vân thú — hai thiên phú cốt lõi của tộc.","anchor":"Vân tộc chúng ta cùng Tinh tộc coi như là hai chủng tộc có nhân số ít nhất trong mười ba tộc"}]},"dinhDanh":"goc","capNhatToi":"@c1662","nguon":["@c1662"],"uyLuc":"Khả năng biến hóa của Vân tộc có thể khiến cả người ở cấp bậc cao hơn cũng không phân biệt được thân phận thật.","dacDiem":"Nhân số thuộc hàng ít nhất trong mười ba tộc nhưng thực lực chỉnh thể luôn xếp trước ba; thành viên thường ẩn giấu thân phận, với bản mạng Vân thú là thiên phú cốt lõi.","congNang":["Thi triển thuật ẩn nấp để che giấu thân phận. @c1662","Dùng thuật biến hóa để cải trang thành thành viên tộc khác, đến mức người có tu vi cao hơn cũng khó phân biệt. @c1662","Sở hữu bản mạng Vân thú, vừa là linh thú vừa là hóa thân của chủ nhân. @c1662","Có thể hợp nhất với bản mạng Vân thú để hóa thành Vân thú cự linh. @c1662"]},{"id":"thach-kiem-toc","name":"Thạch Kiển tộc","cn":"","type":"thanh-toc","typeLabel":"Thánh tộc","diaBan":"Thiên Vân","nhanVatChinh":["Đoạn Thiên Nhận"],"blurb":"Một trong các thánh tộc thuộc liên minh Thiên Vân thập tam tộc, Đoạn Thiên Nhận là đại diện.","detail":"Đoạn Thiên Nhận đại diện Thạch Kiển tộc có mặt tại cuộc họp bí mật truy tìm gián điệp Giác Xi tộc tại Vân Thành.","thanhVien":[{"ten":"Đoạn Thiên Nhận","chucVu":"Đại diện","tuChuong":"@c1664","trangThai":"dang-hoat-dong"}],"nguon":["@c1664"]},{"id":"thuy-mi-bo-lac","name":"Thủy Mị bộ lạc","cn":"","type":"bo-lac","typeLabel":"Bộ lạc","diaBan":"Thiên Vân","nhanVatChinh":["Bạch đạo hữu"],"blurb":"Bộ lạc có tinh nhuệ tinh thông mê hồn thuật, phụ trách truy tìm gián điệp Giác Xi tộc trong Vân Thành.","detail":"Bạch đạo hữu là đại diện Thủy Mị bộ lạc, phụ trách dùng mê hồn thuật kiểm tra người khả nghi vào Vân Thành suốt nửa năm. Tìm được mấy trăm thám tử các tộc nhưng không thấy tung tích Giác Xi tộc.","thanhVien":[{"ten":"Bạch đạo hữu","chucVu":"Phụ trách truy tìm an ninh","tuChuong":"@c1664","trangThai":"dang-hoat-dong"}],"nguon":["@c1664"]},{"id":"van-dang-toc","name":"Vân Đằng Tộc","cn":"","type":"toc","typeLabel":"Tộc","diaBan":"Nghiễm Hàn Giới (liên minh)","nhanVatChinh":["Huynh đệ song sinh Vân Đằng Tộc"],"blurb":"Thượng tộc cửu giai trong liên minh Nghiễm Hàn Giới, có huynh đệ song sinh giỏi liên thủ đối địch tham gia đoàn vào Nghiễm Hàn Giới.","detail":"Thượng tộc cửu giai, cử huynh đệ song sinh am hiểu liên thủ đối địch tham gia đoàn thám hiểm Nghiễm Hàn Giới.","nguon":["@c1670"]},{"id":"di-toc-thap-be","name":"Dị tộc thấp bé","cn":"","type":"chung-toc","typeLabel":"Dị tộc","diaBan":"Nghiễm Hàn Giới","nhanVatChinh":["Sáu dị tộc nhân thấp bé"],"blurb":"Một chủng tộc chưa rõ tên có vóc dáng thấp bé, mặt mang nhiều vệt xám và răng nanh lộ ngoài. Nhóm sáu thành viên xuất hiện sử dụng chiến xa, quái thú kéo xe, cổ kính thăm dò và pháp luân có thể hợp nhất.","detail":"Sáu thành viên của dị tộc này đi trên ba chiến xa cổ xưa và phối hợp chiến đấu thuần thục. Họ phát hiện phế tích đền đài trong bão cát, sau đó liên thủ đối đầu Lôi bằng khôi lỗi.","quyMo":"Ít nhất sáu thành viên xuất hiện","thanhVien":[{"ten":"Sáu dị tộc nhân thấp bé","chucVu":"Nhóm thăm dò","tuChuong":"@c1691","trangThai":"đang hoạt động"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1691","nguon":["@c1691"]},{"id":"hac-nho-toc","name":"Hắc Nho Tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Lôi Minh đại lục","nhanVatChinh":["Gã cầm đầu Hắc Nho Tộc","Sáu dị tộc nhân thấp bé"],"blurb":"Một chủng tộc có quy mô không nhỏ trên Lôi Minh đại lục. Tộc này không am hiểu phi độn thuật nên chủ yếu dựa vào các loại phi xa tự luyện chế để di chuyển và giao chiến.","detail":"Sáu người Hắc Nho Tộc dùng pháp luân, chiến xa và thanh giáp khôi lỗi đánh bại Lôi bằng khôi lỗi nhưng chịu tổn thất nặng. Ngay sau trận chiến, họ bị hơn mười người Giác Xi Tộc phục kích và chặn đường rút lui.","quyMo":"Một chủng tộc không nhỏ trên Lôi Minh đại lục.","quanHe":"Đối địch với toán Giác Xi Tộc tại khu phế tích.","trangThai":"Nhóm sáu người đang bị Giác Xi Tộc bao vây.","thanhVien":[{"ten":"Gã cầm đầu Hắc Nho Tộc","chucVu":"Người cầm đầu nhóm sáu người","tuChuong":"@c1692","trangThai":"đang hoạt động"},{"ten":"Sáu dị tộc nhân thấp bé","chucVu":"Thành viên toán thám hiểm","tuChuong":"@c1692","trangThai":"đang bị vây"}],"tabs":{"tienTrinh":[{"chuong":"@c1692","loai":"khai chiến","importance":"normal","giaiDoan":"Bị Giác Xi Tộc phục kích","text":"Một nhóm sáu người Hắc Nho Tộc bị Giác Xi Tộc bao vây sau khi vừa đánh bại Lôi bằng khôi lỗi và phải liều mạng chống trả.","anchor":"Hắc Nho Tộc tuy rằng cũng là một chủng tộc không nhỏ trên Lôi Minh đại lục nhưng tộc người này lại không am hiểu phi độn thuật","trangThaiMoc":"Nhóm sáu người đang cầm cự trước vòng vây."}]},"capNhatToi":"@c1692","nguon":["@c1692"]},{"id":"tuyet-hong-toc","name":"Tuyết Hống Tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Cực bắc Lôi Minh đại lục","nhanVatChinh":[],"blurb":"Chủng tộc sinh sống tại cực bắc Lôi Minh đại lục, chuyên tu thần thông thuộc tính băng và kỳ thị những con đường tu luyện khác.","detail":"Tuyết Hống Tộc có thực lực tổng thể chỉ ở mức trung bình nhưng từng cá thể sở hữu thân thể và chiến lực mạnh, được Thạch Côn đánh giá không kém tồn tại cao giai Hải Vương Tộc. Thành viên của tộc đã tiến vào Nghiễm Hàn Giới và truy sát Thạch Côn hơn nửa tháng.","tonChi":"Coi băng thuộc tính là căn nguyên của mọi thần thông và bài xích các đường tu luyện khác.","quyMo":"Thực lực tổng thể trung bình.","caoThuManhNhat":"Cá thể có thể sánh với tồn tại cao giai Hải Vương Tộc.","trangThai":"Đang hoạt động tại Nghiễm Hàn Giới","capNhatToi":"@c1694","tabs":{"tienTrinh":[{"chuong":"@c1694","loai":"nhắc tới","importance":"normal","giaiDoan":"Tiến vào Nghiễm Hàn Giới","text":"Tuyết Hống Tộc bất ngờ xuất hiện trong Nghiễm Hàn Giới và truy sát Thạch Côn hơn nửa tháng.","anchor":"không biết tại sao lần này lại không những tiến vào mà còn khiến ta đụng phải","trangThaiMoc":"Đang hoạt động tại Nghiễm Hàn Giới"}]},"nguon":["@c1694"]},{"id":"cac-toc-chiem-cu-dia-vuc-tai-linh-gioi","name":"Các tộc chiếm cứ địa vực tại Linh giới","cn":"","type":"khac","typeLabel":"Các tộc lớn","diaBan":"Linh giới","nhanVatChinh":[],"blurb":"Những tộc đủ khả năng chiếm cứ một khu vực nhất định tại Linh giới.","detail":"Theo lời Thạch Côn, mỗi tộc đạt điều kiện chiếm cứ địa vực sẽ có một khối thiên ngoại kỳ thạch mang Hỗn Độn Vạn Linh Bảng.","quyMo":"Chiếm cứ một khu vực nhất định tại Linh giới","trangThai":"Tồn tại","capNhatToi":"@c1710","tabs":{"tienTrinh":[{"chuong":"@c1710","loai":"nhắc tới","importance":"bridge","giaiDoan":"Điều kiện nhận bảo bảng","text":"Các tộc chiếm cứ được một khu vực nhất định tại Linh giới được nhắc đến như những bên có thiên ngoại kỳ thạch mang Hỗn Độn Vạn Linh Bảng.","anchor":"phàm là tộc này có tài năng chiếm cứ một khu vực nhất định ở Linh giới"}]},"nguon":["@c1710"]},{"id":"nhung-toc","name":"Nhung Tộc","cn":"","type":"chủng tộc","typeLabel":"Dị tộc","diaBan":"","nhanVatChinh":["Người Nhung Tộc sử dụng hắc phiên","Người Nhung Tộc sử dụng lục kính","Người Nhung Tộc sử dụng hồng châu","Người Nhung Tộc sử dụng hôi sắc kiếm quang"],"blurb":"Một dị tộc có các thành viên phủ lông mao xanh biếc và mang đầu giống lang sói. Bốn người Nhung Tộc dùng chiến xa hợp thể truy sát nhóm Nguyệt tiên tử rồi giao chiến với Hàn Lập.","detail":"Bốn thành viên Nhung Tộc hợp nhất chiến xa thành một cỗ chiến xa hình thoi có khả năng xuyên không truy kích. Khi Hàn Lập can thiệp cứu Khúc nhi, họ dùng hắc phiên, lục kính, hồng châu, phi đao và hôi sắc kiếm quang để giao chiến.","thanhVien":[{"ten":"Người Nhung Tộc sử dụng hắc phiên","chucVu":"","tuChuong":"@c1729","trangThai":"không rõ"},{"ten":"Người Nhung Tộc sử dụng lục kính","chucVu":"","tuChuong":"@c1729","trangThai":"đang hoạt động"},{"ten":"Người Nhung Tộc sử dụng hồng châu","chucVu":"","tuChuong":"@c1729","trangThai":"đang hoạt động"},{"ten":"Người Nhung Tộc sử dụng hôi sắc kiếm quang","chucVu":"","tuChuong":"@c1729","trangThai":"đang hoạt động"}],"quanHe":"Giao chiến với Hàn Lập và truy sát nhóm Nguyệt tiên tử.","trangThai":"đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c1729","loai":"khai chiến","importance":"normal","giaiDoan":"Truy sát trong Nghiễm Hàn Giới","text":"Bốn thành viên Nhung Tộc dùng chiến xa hợp thể truy sát nhóm Nguyệt tiên tử và giao chiến trực tiếp với Hàn Lập.","anchor":"Ai! Ai dám ngăn cản chuyện của Nhung tộc ta?","trangThaiMoc":"đang giao chiến"}]},"capNhatToi":"@c1729","nguon":["@c1729"]}]};
